37: /**
38:  * ActionAddAllClassesFromModel enables pasting of an existing node into a 
39:  * Diagram.
40:  *
41:  * @author Timothy M. Lebo (Oct 2003)
42:  * Smart Information Flow Technologies.
43:  */
44: public class ActionAddAllClassesFromModel extends UMLAction {
45: 
46:     // Instance Variables
47:     protected String tabName;
48:     protected Object object;
49: 
50:     /**
51:      * Constructor
52:      */
53:     public ActionAddAllClassesFromModel(String tabName) {
54:         super(tabName, NO_ICON);
55:         this.tabName = tabName;
56:     }
57: 
58:     /**
59:      * Constructor
60:      */
61:     public ActionAddAllClassesFromModel(String tabName, Object o) {
62:         super(tabName, NO_ICON);
63:         this.tabName = tabName;
64:         object = o;
65:     }
66: 
67:     /**
68:      * shouldBeEnabled
69:      *
70:      * Returns true if this popup menu item should be enabled, false
71:      * if it should be grayed out.
72:      *
73:      * @author Timothy M. Lebo (Oct 2003)
74:      * Smart Information Flow Technologies.
75:      */
76:     public boolean shouldBeEnabled() {	
77: 	return object instanceof UMLClassDiagram;
78:     }
79: 
80:     /**
81:      * actionPerformed
82:      *
83:      * Finds all of the classes within the same namespace as the
84:      * UMLClassDiagram that was given to me in my constructor and adds
85:      * them to the UMLClassDiagram.
86:      *
87:      * @param ae - the ActionEvent
88:      *
89:      * @author Timothy M. Lebo (Oct 2003)
90:      * Smart Information Flow Technologies.
91:      */
92:     public void actionPerformed(ActionEvent ae) {
93: 
94: 	if ( object instanceof UMLClassDiagram ) {
95: 
96: 	    // Use DiagramInterface to add classes to diagram
97: 	    DiagramInterface diagram =
98: 		new DiagramInterface( Globals.curEditor() );
99: 	    diagram.setCurrentDiagram( (UMLClassDiagram) object);
100: 
101: 	    Object namespace = ((UMLClassDiagram) object).getNamespace();
102: 	    Iterator elements =
103: 		ModelFacade.getOwnedElements( namespace ).iterator();
104: 	    while ( elements.hasNext() ) {
105: 		Object element = elements.next();
106: 		if ( ModelFacade.isAClass(element) ) {
107: 		    diagram.addClass( element , false );
108: 		}
109: 	    }
110: 	}
111:     }
112: 
113: } // ActionAddAllClassesFromModel
