89: /**
90:  * Abstract class to display diagram lines (edges) for UML ModelElements that
91:  * look like lines and that have editable names.
92:  */
93: public abstract class FigEdgeModelElement
94:     extends FigEdgePoly
95:     implements
96:         VetoableChangeListener,
97:         DelayedVChangeListener,
98:         MouseListener,
99:         KeyListener,
100:         PropertyChangeListener,
101:         NotationContext,
102:         ArgoNotationEventListener,
103:         Highlightable {
104: 
105:     protected static final Logger LOG =
106:         Logger.getLogger(FigEdgeModelElement.class);
107: 
108:     private DiElement diElement = null;
109: 
110:     /**
111:      * Set the removeFromDiagram to false if this edge may not
112:      * be removed from the diagram.
113:      */
114:     private boolean removeFromDiagram = true;
115: 
116:     ////////////////////////////////////////////////////////////////
117:     // constants
118: 
119:     private static final Font LABEL_FONT;
120:     private static final Font ITALIC_LABEL_FONT;
121: 
122:     static {
123:         LABEL_FONT = new Font("Dialog", Font.PLAIN, 10);
124:         ITALIC_LABEL_FONT =
125:             new Font(LABEL_FONT.getFamily(), Font.ITALIC, LABEL_FONT.getSize());
126:     }
127: 
128:     /**
129:      * Offset from the end of the set of popup actions at which new items
130:      * should be inserted by concrete figures.
131:     **/
132:     private static int popupAddOffset;
133: 
134:     ////////////////////////////////////////////////////////////////
135:     // instance variables
136: 
137:     /**
138:      * The Fig that displays the name of this model element.
139:      * Use getNameFig(), no setter should be required.
140:      */
141:     private FigText nameFig;
142: 
143:     /**
144:      * Use getStereotypeFig(), no setter should be required.
145:      */
146:     private Fig stereotypeFig;
147: 
148:     private FigCommentPort edgePort;
149: 
150:     private ItemUID itemUid;
151: 
152:     /**
153:      * The current notation for this fig. The notation is for example
154:      * UML 1.3 or Java
155:      */
156:     private NotationName currentNotationName;
157: 
158:     /*
159:      * List of model element listeners we've registered.
160:      */
161:     private Collection listeners = new ArrayList();
162: 
163:     ////////////////////////////////////////////////////////////////
164:     // constructors
165: 
166:     /** Partially construct a new FigNode.  This method creates the
167:      *  _name element that holds the name of the model element and adds
168:      *  itself as a listener. */
169:     public FigEdgeModelElement() {
170: 
171:         nameFig = new FigSingleLineText(10, 30, 90, 20, false);
172:         nameFig.setTextFilled(false);
173: 
174:         stereotypeFig = new FigStereotypesCompartment(10, 10, 90, 15);
175: 
176:         setBetweenNearestPoints(true);
177:         ArgoEventPump.addListener(ArgoEventTypes.ANY_NOTATION_EVENT, this);
178:         currentNotationName = Notation.getConfigueredNotation();
179:     }
180: 
181:     /**
182:      * The constructor that hooks the Fig into the UML model element.
183:      *
184:      * @param edge the UML element
185:      */
186:     public FigEdgeModelElement(Object edge) {
187:         this();
188:         setOwner(edge);
189:         ArgoEventPump.addListener(ArgoEventTypes.ANY_NOTATION_EVENT, this);
190:     }
191: 
192:     /**
193:      * @see java.lang.Object#finalize()
194:      */
195:     protected void finalize() {
196:         ArgoEventPump.removeListener(ArgoEventTypes.ANY_NOTATION_EVENT, this);
197:     }
198: 
199:     /**
200:      * Create a FigCommentPort if needed
201:      */
202:     public void makeCommentPort() {
203:         if (edgePort == null) {
204:             edgePort = new FigCommentPort();
205:             edgePort.setOwner(getOwner());
206:             edgePort.setVisible(false);
207:             addPathItem(edgePort,
208:                     new PathConvPercent(this, 50, 0));
209:         }
210:     }
