238:     /**
239:      * @see org.tigris.gef.presentation.Fig#getTipString(java.awt.event.MouseEvent)
240:      */
241:     public String getTipString(MouseEvent me) {
242:         ToDoItem item = hitClarifier(me.getX(), me.getY());
243:         String tip = "";
244:         if (item != null
245:             && Globals.curEditor().getSelectionManager().containsFig(this)) {
246:             tip = item.getHeadline();
247:         } else if (getOwner() != null) {
248:             tip = Model.getFacade().getTipString(getOwner());
249:         } else {
250:             tip = toString();
251:         }
252: 
253:         if (tip != null && tip.length() > 0 && !tip.endsWith(" ")) {
254:             tip += " ";
255:         }
256:         return tip;
257:     }
258: 
259:     /**
260:      * @see org.tigris.gef.ui.PopupGenerator#getPopUpActions(java.awt.event.MouseEvent)
261:      */
262:     public Vector getPopUpActions(MouseEvent me) {
263:         Vector popUpActions = super.getPopUpActions(me);
264:         
265:         // TODO: Remove this line after 0.20.
266:         // This is a hack that removes the ordering menu according to issue 3645
267:         popUpActions.remove(0);
268: 
269:         // popupAddOffset should be equal to the number of items added here:
270:         popUpActions.addElement(new JSeparator());
271:         popupAddOffset = 1;
272:         if (removeFromDiagram) {
273:             popUpActions.addElement(
274:                     ProjectBrowser.getInstance().getRemoveFromDiagramAction());
275:             popupAddOffset++;
276:         }
277:         popUpActions.addElement(new ActionDeleteModelElements());
278:         popupAddOffset++;
279: 
280:         /* Check if multiple items are selected: */
281:         boolean ms = TargetManager.getInstance().getTargets().size() > 1;
282:         if (!ms) {
283:             ToDoList list = Designer.theDesigner().getToDoList();
284:             Vector items =
285:                 (Vector) list.elementsForOffender(getOwner()).clone();
286:             if (items != null && items.size() > 0) {
287:                 ArgoJMenu critiques = new ArgoJMenu("menu.popup.critiques");
288:                 ToDoItem itemUnderMouse = hitClarifier(me.getX(), me.getY());
289:                 if (itemUnderMouse != null) {
290:                     critiques.add(new ActionGoToCritique(itemUnderMouse));
291:                     critiques.addSeparator();
292:                 }
293:                 int size = items.size();
294:                 for (int i = 0; i < size; i++) {
295:                     ToDoItem item = (ToDoItem) items.elementAt(i);
296:                     if (item == itemUnderMouse)
297:                         continue;
298:                     critiques.add(new ActionGoToCritique(item));
299:                 }
300:                 popUpActions.insertElementAt(new JSeparator(), 0);
301:                 popUpActions.insertElementAt(critiques, 0);
302:             }
303:         }
304:         // Add stereotypes submenu
305:         Action[] stereoActions = getApplyStereotypeActions();
306:         if (stereoActions != null) {
307:             popUpActions.insertElementAt(new JSeparator(), 0);
308:             ArgoJMenu stereotypes = new ArgoJMenu(
309:                     "menu.popup.apply-stereotypes");
310:             for (int i = 0; i < stereoActions.length; ++i) {
311:                 stereotypes.addCheckItem(stereoActions[i]);
312:             }
313:             popUpActions.insertElementAt(stereotypes, 0);
314:         }
315:         return popUpActions;
316:     }
317:     
318:     /**
319:      * Get the set of Actions which valid for adding/removing
320:      * Stereotypes on the ModelElement of this Fig's owner.
321:      *  
322:      * @return array of Actions 
323:      */
324:     protected Action[] getApplyStereotypeActions() {
325:         return StereotypeUtility.getApplyStereotypeActions(getOwner());
326:     }
327: 
328:     /**
329:      * distance formula: (x-h)^2 + (y-k)^2 = distance^2
330:      *
331:      * @param p1 point
332:      * @param p2 point
333:      * @return the square of the distance
334:      */
335:     public int getSquaredDistance(Point p1, Point p2) {
336:         int xSquared = p2.x - p1.x;
337:         xSquared *= xSquared;
338:         int ySquared = p2.y - p1.y;
339:         ySquared *= ySquared;
340:         return xSquared + ySquared;
341:     }
