62: public class SelectionComponentInstance extends SelectionWButtons {
63:     protected static Category cat = 
64:         Category.getInstance(SelectionComponentInstance.class);
65:   ////////////////////////////////////////////////////////////////
66:   // constants
67:   public static Icon dep = ResourceLoaderWrapper.getResourceLoaderWrapper().lookupIconResource("Dependency");
68:   public static Icon depRight = 
69:       ResourceLoaderWrapper.getResourceLoaderWrapper().lookupIconResource("DependencyRight");
