77:     /**
78:      * Returns all subsystems found in this namespace and in its children.
79:      *
80:      * @param ns is the namespace
81:      * @return Collection
82:      */
83:     public Collection getAllSubSystems(Object ns) {
84:         if (ns == null) {
85:             return new ArrayList();
86:         }
87:         if (!(ns instanceof MNamespace)) {
88:             throw new IllegalArgumentException();
89:         }
90: 
91:         Iterator it = ((MNamespace) ns).getOwnedElements().iterator();
92:         List list = new ArrayList();
93:         while (it.hasNext()) {
94:             Object o = it.next();
95:             if (o instanceof MNamespace) {
96:                 list.addAll(getAllSubSystems(o));
97:             }
98:             if (o instanceof MSubsystem) {
99:                 list.add(o);
100:             }
101: 
102:         }
103:         return list;
104:     }
