177:     /**
178:      * Returns all modelelements found in this namespace and its children
179:      * that are of some class kind.<p>
180:      *
181:      * This method is CPU intensive and therefore needs to be as efficient as
182:      * possible.<p>
183:      *
184:      * @param nsa is the namespace
185:      * @param type is the class kind
186:      * @return Collection
187:      */
188:     public Collection getAllModelElementsOfKind(Object nsa, Object type) {
189:         if (type instanceof String) {
190:             return getAllModelElementsOfKind(nsa, (String) type);
191:         }
192:         Class kind = (Class) type;
193:         if (nsa == null || kind == null) {
194:             return Collections.EMPTY_LIST;
195:         }
196: 
197:         if (!ModelFacade.isANamespace(nsa)) {
198:             throw new IllegalArgumentException(
199:                 "given argument " + nsa + " is not a namespace");
200:         }
201: 
202:         Collection elementsCol = ModelFacade.getOwnedElements(nsa);
203: 
204:         // only continue if there are owned elements
205:         if (elementsCol == Collections.EMPTY_LIST
206: 	    || elementsCol.size() == 0) {
207:             return Collections.EMPTY_LIST;
208:         }
209: 
210:         // use array for speed over iterator
211:         Object[] elements = elementsCol.toArray();
212:         Object element = null;
213:         // only instantiate arraylist when needed
214:         List list = Collections.EMPTY_LIST;
215: 
216:         for (int i = 0; i < elements.length; i++) {
217: 
218:             element = elements[i];
219: 
220:             if (element instanceof MNamespace) {
221: 
222:                 if (list == Collections.EMPTY_LIST) {
223:                     list = new ArrayList(elements.length);
224:                 }
225: 
226:                 // get child model elements recursively
227:                 Collection elementsCol1 =
228: 		    getAllModelElementsOfKind(element, kind);
229: 
230:                 // only add model elements if there are some
231:                 if (!(elementsCol1 == Collections.EMPTY_LIST)
232: 		    && !(elementsCol1.size() == 0)) {
233: 
234: 		    list.addAll(elementsCol1);
235: 
236:                 }
237: 
238:             }
239:             if (kind.isAssignableFrom(element.getClass())) {
240: 
241:                 if (list == Collections.EMPTY_LIST) {
242:                     list = new ArrayList(elements.length);
243:                 }
244: 
245:                 list.add(element);
246:             }
247:         }
248:         return list;
249: 
250:     }
