253:      * Helper method for {@link #getAllModelElementsOfKind(Object, Class)}.
254:      *
255:      * @param nsa namespace.
256:      * @param kind name of class to find, this implementation will add the "M"
257:      *             for NSUML.
258:      * @return a Collection.
259:      */
260:     public Collection getAllModelElementsOfKind(Object nsa, String kind) {
261: 
262:         if (nsa == null || kind == null) {
263:             return Collections.EMPTY_LIST;
264:         }
265:         if (!ModelFacade.isANamespace(nsa)) {
266:             throw new IllegalArgumentException(
267:                 "given argument " + nsa + " is not a namespace");
268:         }
269:         Collection col = null;
270:         try {
271:             // TODO: This assumes we are working with MThings
272:             col = getAllModelElementsOfKind(nsa, Class.forName("M" + kind));
273:         } catch (ClassNotFoundException cnfe) {
274:             LOG.error(cnfe);
275:             return Collections.EMPTY_LIST;
276:         }
277:         return col;
