390:     /**
391:      * Utility function for managing several overlayed models, eg a user
392:      * model to which elements from some profile models is imported when
393:      * needed. This version of the function assumes it is permissible to
394:      * create missing elements.
395:      *
396:      * This function may fail and return null eg if some required object
397:      * doesn't exist in the target model and cannot be copied.
398:      *
399:      * @param elem is some element.
400:      * @param model is the model the returned object shall belong to.
401:      * @return An element of the same type and at the same position in the
402:      *  model as elem, or if that would turn out impossible then null.
403:      */
404:     public Object getCorrespondingElement(Object elem, Object model) {
405:     return getCorrespondingElement(elem, model, true);
406:     }
407: 
408:     /**
409:      * Utility function for managing several overlayed models, eg a user
410:      * model to which elements from some profile models is imported when
411:      * needed. This version of the function will only copy objects if
412:      * canCreate is true, but may then also copy other missing elements.
413:      *
414:      * This function may fail and return null eg if the required object
415:      * doesn't exist in the target model and canCreate is false or some
416:      * required object doesn't exist in the target model and cannot be
417:      * copied.
418:      *
419:      * @param elem is some element.
420:      * @param model is the model the returned object shall belong to.
421:      * @param canCreate determines if objects can be copied into model.
422:      * @return An element of the same type and at the same position in the
423:      *  model as elem, or if that would turn out impossible then null.
424:      */
425:     public Object getCorrespondingElement(Object elem,
426:                      Object model, boolean canCreate) {
427:         if (elem == null || model == null || !(elem instanceof MModelElement)) {
428:             throw new NullPointerException();
429:         }
430: 
431:         // Trivial case
432:         if (((MModelElement) elem).getModel() == model) {
433:             return elem;
434:         }
435: 
436:         // Base case
437:         if (elem instanceof MModel) {
438:             return model;
439:         }
440: 
441:         // The cast is actually safe
442:         MNamespace ns =
443:             (MNamespace) getCorrespondingElement(
444:                     ((MModelElement) elem).getNamespace(), model, canCreate);
445:         if (ns == null) {
446:             return null;
447:         }
448: 
449:         Iterator it = ns.getOwnedElements().iterator();
450:         while (it.hasNext()) {
451:             MModelElement e = (MModelElement) it.next();
452:             if (e.getClass() == ((MModelElement) elem).getClass()
453:                 && ((((MModelElement) elem).getName() == null
454:                      && e.getName() == null)
455:                     || (((MModelElement) elem).getName() != null
456:                         && ((MModelElement) elem).getName().equals(
457:                                 e.getName())))) {
458:                 return e;
459:             }
460:         }
461: 
462:         if (!canCreate) {
463:             return null;
464:         }
465: 
466:         return nsmodel.getCopyHelper().copy(elem, ns);
467:     }
468: 
469:     /**
470:      * Tests if two objects are of the same type, have the same name and the
471:      * same relative position in the model.
472:      *
473:      * Same relative position implies either:
474:      * * their owners correspond to eachother.
475:      * * they are both owned by model objects.
476:      *
477:      * @param obj1 is an object.
478:      * @param obj2 is another object.
479:      * @return true if obj1 corresponds to obj2, false otherwise.
480:      */
481:     public boolean corresponds(Object obj1, Object obj2) {
482:         if (!(obj1 instanceof MModelElement)) {
483:             throw new IllegalArgumentException("obj1");
484:         }
485:         if (!(obj2 instanceof MModelElement)) {
486:             throw new IllegalArgumentException("obj2");
487:         }
488: 
489:         if (obj1 instanceof MModel && obj2 instanceof MModel) {
490:             return true;
491:         }
492:         if (obj1.getClass() != obj2.getClass()) {
493:             return false;
494:         }
495: 
496:         MModelElement modelElement1 = (MModelElement) obj1;
497:         MModelElement modelElement2 = (MModelElement) obj2;
498:         if ((modelElement1.getName() == null
499:              && modelElement2.getName() != null)
500: 	    || (modelElement1.getName() != null
501: 	        && !modelElement1.getName().equals(modelElement2.getName()))) {
502: 
503:             return false;
504: 
505: 	}
506:         return corresponds(modelElement1.getNamespace(),
507:                 	   modelElement2.getNamespace());
508:     }
509: 
510:     /**
511:      * Checks if a child for some ownershiprelationship (as in a
512:      * namespace A is owned by a namespace B) is allready in the
513:      * ownerhship relation.
514:      *
515:      * @param parent The current leaf for the ownership relation
516:      * @param child The child that should be owned by the parent
517:      * @return true if the child is allready in the ownership relationship
518:      */
519:     public boolean isCyclicOwnership(Object parent, Object child) {
520:         return (getOwnerShipPath(parent).contains(child) || parent == child);
521:     }
522: 
523: 
524:     private List getOwnerShipPath(Object elem) {
525:         if (ModelFacade.isABase(elem)) {
526:             List ownershipPath = new ArrayList();
527:             Object parent = ModelFacade.getModelElementContainer(elem);
528:             while (parent != null) {
529:                 ownershipPath.add(parent);
530:                 parent = ModelFacade.getModelElementContainer(parent);
531:             }
532:             return ownershipPath;
533:         }
534:         throw new IllegalArgumentException("Not a base");
535:     }
536: }
