1513:      * could possibly fire.
1514:      * @param modelClass
1515:      * @return The event keys.
1516:      */
1517:     public synchronized EventKey[] getEventTypes(Class modelClass) {
1518:         modelClass = formatClass(modelClass);
1519:         Map nameMap = (Map) definition.get(modelClass);
1520:         Iterator it = nameMap.keySet().iterator();
1521:         int size = 0;
1522:         while (it.hasNext()) {
1523:             size += ((int[]) nameMap.get(it.next())).length;
1524:         }
1525:         EventKey[] result = new EventKey[size + 1];
1526:         int counter = 0;
1527:         it = nameMap.keySet().iterator();
1528:         while (it.hasNext()) {
1529:             String name = (String) it.next();
1530:             int[] types = (int[]) nameMap.get(name);
1531:             EventKey[] keys = new EventKey[types.length];
1532:             for (int i = 0; i < types.length; i++) {
1533:                 keys[i] = new EventKey(types[i], name);
1534:             }
1535:             System.arraycopy(keys, 0, result, counter, keys.length);
1536:             counter += keys.length;
1537:         }
1538:         // remove event
1539:         System.arraycopy(new EventKey[] {
1540: 	    new EventKey(0, null),
1541: 	},
1542: 			 0,
1543: 			 result,
1544: 			 counter,
1545: 			 1);
1546:         return result;
1547:     }
1548: 
1549:     /**
1550:      * Returns all EventKeys (eventdefinitions) with the given eventName 
1551:      * that the given modelClass can fire.
1552:      * @param modelClass
1553:      * @param name
1554:      * @return All event keys.
1555:      */
1556:     public synchronized EventKey[] getEventTypes(Class modelClass,
1557:                                                  String name) {
1558:         modelClass = formatClass(modelClass);
1559:         Map nameMap = (Map) definition.get(modelClass);
1560:         if (nameMap != null) {
1561:             int[] types = (int[]) nameMap.get(name);
1562:             if (types != null) {
1563: 
1564:                 EventKey[] keys = new EventKey[types.length];
1565:                 for (int i = 0; i < types.length; i++) {
1566:                     keys[i] = new EventKey(types[i], name);
1567:                 }
1568:                 return keys;
1569:             }
1570:         }
1571:         return new EventKey[0];
1572:     }
