50:     private Project project;
51:     private URL url;
52:     private Map instance;
53:     
54:     /**
55:      * The constructor.
56:      * 
57:      * @param theUrl the location where the diagram members 
58:      *               are stored persistently
59:      * @param theProject the project to persist
60:      * @throws SAXException when SAX finds a problem
61:      */
62:     public DiagramMemberFilePersister(URL theUrl, Project theProject)
63:         throws SAXException {
64:         this.url = theUrl;
