507:      * @param fromClassifier   the first given classifier
508:      * @param aggregationKind1 the first aggregationkind
509:      * @param toClassifier     the second given classifier
510:      * @param aggregationKind2 the second aggregationkind
511:      * @param unidirectional true if unidirectional
512:      * @return the newly build binary associationrole
513:      */
514:     public Object buildAssociation(
515: 					 Object fromClassifier,
516: 					 Object aggregationKind1,
517: 					 Object toClassifier,
518: 					 Object aggregationKind2,
519: 					 Boolean unidirectional) {
520:         if (fromClassifier == null || toClassifier == null) {
521:                 throw new IllegalArgumentException("one of "
522:         				       + "the classifiers to be "
523:         				       + "connected is null");
524:         }
525:         MClassifier from = (MClassifier) fromClassifier;
526:         MClassifier to = (MClassifier) toClassifier;
527:         MAggregationKind agg1 = (MAggregationKind) aggregationKind1;
528:         MAggregationKind agg2 = (MAggregationKind) aggregationKind2;
529: 
530:         MNamespace ns1 = from.getNamespace();
531:         MNamespace ns2 = to.getNamespace();
532:         if (ns1 == null || ns2 == null) {
533:                 throw new IllegalArgumentException("one of "
534:         				       + "the classifiers does not "
535:         				       + "belong to a namespace");
536:         }
537:         MAssociation assoc =
538:                 Model.getUmlFactory().getCore().createAssociation();
539:         assoc.setName("");
540:         assoc.setNamespace(
541:         		   Model.getCoreHelper().getFirstSharedNamespace(ns1,
542:         								  ns2));
543: 
544:         boolean nav1 = true;
545:         boolean nav2 = true;
546: 
547:         if (from instanceof MInterface) {
548:             nav2 = false;
549:             agg2 = agg1;
550:             agg1 = null;
551:         } else if (to instanceof MInterface) {
552:             nav1 = false;
553:         } else {
554:             nav1 = !Boolean.TRUE.equals(unidirectional);
555:             nav2 = true;
556:         }
557: 
558:         buildAssociationEnd(
559: 			    assoc,
560: 			    null,
561: 			    from,
562: 			    null,
563: 			    null,
564: 			    nav1,
565: 			    null,
566: 			    agg1,
567: 			    null,
568: 			    null,
569: 			    null);
570:         buildAssociationEnd(
571: 			    assoc,
572: 			    null,
573: 			    to,
574: 			    null,
575: 			    null,
576: 			    nav2,
577: 			    null,
578: 			    agg2,
579: 			    null,
580: 			    null,
581: 			    null);
582: 
583:         return assoc;
584:     }
