48: /**
49:  * A Mode to interpret user input while creating a comment edge.
50:  * The comment can connect an existing comment node to any other existing
51:  * If the association is an n-ary association (diamond shape node) then
52:  * the edge is simply added.
53:  * If the association is a binary association edge then that edge is
54:  * transformed into a n-ary association.
55:  *
56:  * @author pepargouml@yahoo.es
57:  */
58: public class ModeCreateCommentEdge extends ModeCreatePolyEdge {
59:     
60:     private FigNode newFigNodeAssociation;
61:     private FigEdgeModelElement sourceEdge;
62:     private Object sourceModelElement;
63:     private Collection associationEnds;
64: 
65: 
66:     /**
67:      * @see java.awt.event.MouseListener#mousePressed(java.awt.event.MouseEvent)
68:      */
69:     public void mousePressed(MouseEvent me) {
70:         int x = me.getX(), y = me.getY();
71:         Fig underMouse = editor.hit(x, y);
72:         if (underMouse == null) {
73:             underMouse = editor.hit(x - 16, y - 16, 32, 32);
74:         }
75:         
76:         if (underMouse == null && _npoints == 0) {
77:             done();
78:             me.consume();
79:             return;
80:         }
81: 
82:         if (_npoints > 0) {
83:             me.consume();
84:             return;
85:         }
86:         
87:         Object modelElement = underMouse.getOwner();
88:         
89:         if (underMouse instanceof FigEdgeModelElement) {
90:             // If we're drawing from an edge
91:             
92:             sourceEdge = (FigEdgeModelElement) underMouse;
93:             sourceModelElement = sourceEdge.getOwner();
94:             
95:             FigTee commentPort = new FigTee();
96:             commentPort.setOwner(sourceModelElement);
97:             sourceEdge.addTeeFig(commentPort);
98:             
99:             underMouse = commentPort;
100:             setSourceFigNode(commentPort);
101:             setStartPort(sourceModelElement);
102:             setStartPortFig(commentPort);
103:         } else if (underMouse instanceof FigNodeModelElement) {
104:             if (getSourceFigNode() == null) {
105:                 setSourceFigNode((FigNode) underMouse);
106:                 setStartPort(getSourceFigNode().deepHitPort(x, y));
107:             }
108:             if (getStartPort() == null) {
109:                 done();
110:                 me.consume();
111:                 return;
112:             }
113:             setStartPortFig(
114:                     getSourceFigNode().getPortFig(getStartPort()));
115:         } else {
116:             done();
117:             me.consume();
118:             return;
119:         }
120: 
121:         createFig(me);
122:         me.consume();
123:     }
124: 
125:     /**
126:      * @see org.tigris.gef.base.ModeCreatePolyEdge#mouseReleased(java.awt.event.MouseEvent)
127:      */
128:     public void mouseReleased(MouseEvent me) {
129:         if (me.isConsumed()) {
130:             return;
131:         }
132:         if (getSourceFigNode() == null) {
133:             done();
134:             me.consume();
135:             return;
136:         }
137:         int x = me.getX(), y = me.getY();
138:         Fig destFig = editor.hit(x, y);
139:         if (destFig == null) {
140:             destFig = editor.hit(x - 16, y - 16, 32, 32);
141:         }
142:         GraphModel graphModel = editor.getGraphModel();
143:         if (!(graphModel instanceof MutableGraphModel)) {
144:             destFig = null;
145:         }
146:         
147:         
148:         MutableGraphModel mutableGraphModel = (MutableGraphModel) graphModel;
149:         // TODO: potential class cast exception
150:         if (destFig instanceof FigAssociation && 
151:                 !(destFig instanceof FigAssociationClass)) {
152:             Object association = destFig.getOwner();
153:             boolean isValid =
154:                 Model.getUmlFactory().isConnectionValid(
155:                     Model.getMetaTypes().getAssociationEnd(),
156:                     getStartPort(),
157:                     association);
158:             if (isValid) {
159:                 GraphModel gm = editor.getGraphModel();
160:                 GraphNodeRenderer renderer = editor.getGraphNodeRenderer();
161:                 Layer lay = editor.getLayerManager().getActiveLayer();
162:                 mutableGraphModel.removeEdge(association);
163:                 destFig.setOwner(null);
164:                 destFig.removeFromDiagram();
165:                 mutableGraphModel.addNode(association);
166:                 FigNode figNode = (FigNode) lay.presentationFor(association);
167:                 figNode.setLocation(
168:                         x - figNode.getWidth() / 2,
169:                         y - figNode.getHeight() / 2);
170:                 editor.add(figNode);
171:                 associationEnds = 
172:                     Model.getFacade().getConnections(association);
173:                 Iterator it = associationEnds.iterator();
174:                 mutableGraphModel.addEdge(it.next());
175:                 mutableGraphModel.addEdge(it.next());
176:                 destFig = figNode;
177:             }
178:         }
179: 
180:         if (destFig instanceof FigNode &&
181:                 !(destFig instanceof FigClassAssociationClass) &&
182:                 !Model.getFacade().isANaryAssociation(destFig.getOwner())) {
183:             FigNode destFigNode = (FigNode) destFig;
184:             // If its a FigNode, then check within the
185:             // FigNode to see if a port exists
186:             Object foundPort = destFigNode.deepHitPort(x, y);
187: 
188:             if (foundPort == getStartPort() && _npoints < 4) {
189:                 // user made a false start
190:                 done();
191:                 me.consume();
192:                 return;
193:             }
194:             if (foundPort != null) {
195:                 Fig destPortFig = destFigNode.getPortFig(foundPort);
196:                 FigPoly p = (FigPoly) _newItem;
197:                 if (foundPort == getStartPort() && _npoints >= 4) {
198:                     p.setSelfLoop(true);
199:                 }
200:                 editor.damageAll();
201:                 p.setComplete(true);
202: 
203:                 Object edgeType = getArg("edgeClass");
204:                 setNewEdge(mutableGraphModel.connect(
205:                        getStartPort(), foundPort, (Class) edgeType));
206: 
207:                 // Calling connect() will add the edge to the GraphModel and
208:                 // any LayerPersectives on that GraphModel will get a
209:                 // edgeAdded event and will add an appropriate FigEdge
210:                 // (determined by the GraphEdgeRenderer).
211: 
212:                 if (getNewEdge() != null) {
213:                     getSourceFigNode().damage();
214:                     destFigNode.damage();
215:                     Layer lay = editor.getLayerManager().getActiveLayer();
216:                     FigEdge fe = (FigEdge) lay.presentationFor(getNewEdge());
217:                     _newItem.setLineColor(Color.black);
218:                     fe.setFig(_newItem);
219:                     fe.setSourcePortFig(getStartPortFig());
220:                     fe.setSourceFigNode(getSourceFigNode());
221:                     fe.setDestPortFig(destPortFig);
222:                     fe.setDestFigNode(destFigNode);
223: 
224:                     if (fe != null) {
225:                         editor.getSelectionManager().select(fe);
226:                     }
227:                     editor.damageAll();
228: 
229:                     // if the new edge implements the MouseListener
230:                     // interface it has to receive the mouseReleased() event
231:                     if (fe instanceof MouseListener) {
232:                         ((MouseListener) fe).mouseReleased(me);
233:                     }
234: 
235:                     // set the new edge in place
236:                     if (getSourceFigNode() != null) {
237:                         getSourceFigNode().updateEdges();
238:                     }
239:                     if (destFigNode != null) {
240:                         destFigNode.updateEdges();
241:                     }
242:                     endAttached();
243:                 }
244:                 done();
245:                 me.consume();
246:                 return;
247:             }
248:         }
249:         if (!nearLast(x, y)) {
250:             editor.damageAll();
251:             Point snapPt = new Point(x, y);
252:             editor.snap(snapPt);
253:             ((FigPoly) _newItem).addPoint(snapPt.x, snapPt.y);
254:             _npoints++;
255:             editor.damageAll();
256:         }
257:         _lastX = x;
258:         _lastY = y;
259:         me.consume();
260: 
261:         /* If a FigNodeAssociation has been created and placed but
262:          * the connection fails, it must be undone.
263:          */
264:         if (getNewEdge() == null
265:                 && newFigNodeAssociation != null
266:                 && newFigNodeAssociation instanceof FigNodeAssociation) {
267:             Editor editor = Globals.curEditor();
268:             editor.remove(newFigNodeAssociation);
269:             newFigNodeAssociation.removeFromDiagram();
270:             sourceEdge.setOwner(sourceModelElement);
271:         }
272:     }
273: 
274:     /**
275:      * This will be called when the edge is successfully connected.
276:      * What we do in this class is to determine if we are creating
277:      * an n-ary association. If so then FigNode representing the n-ary
278:      * association is made visible. The FigEdge representing the old
279:      * binary association is removed and replaced with edges representing
280:      * the 2 association ends of that original fig.
281:      */
282:     protected void endAttached() {
283:         if (newFigNodeAssociation != null) {
284:             newFigNodeAssociation.setVisible(true);
285: 
286:             Editor editor = Globals.curEditor();
287: 
288:             GraphModel gm = editor.getGraphModel();
289:             if (gm instanceof MutableGraphModel) {
290:                 MutableGraphModel mutableGraphModel = (MutableGraphModel) gm;
291:                 Iterator it = associationEnds.iterator();
292:                 mutableGraphModel.addEdge(it.next());
293:                 mutableGraphModel.addEdge(it.next());
294:                 editor.getSelectionManager().deselectAll();
295:                 mutableGraphModel.addNode(sourceModelElement);
296:             }
297:         }
298:         super.endAttached();
299:     }
300: 
301:     private FigNode placeTempNode(MouseEvent me) {
302:         Editor editor = Globals.curEditor();
303:         FigNode figNode = null;
304:         GraphModel gm = editor.getGraphModel();
305: 
306:         GraphNodeRenderer renderer = editor.getGraphNodeRenderer();
307:         Layer lay = editor.getLayerManager().getActiveLayer();
308:         figNode = renderer.getFigNodeFor(gm, lay, sourceModelElement, null);
309:         figNode.setLocation(
310:                 me.getX() - figNode.getWidth() / 2,
311:                 me.getY() - figNode.getHeight() / 2);
312:         figNode.setVisible(false);
313:         editor.add(figNode);
314:         editor.getSelectionManager().deselectAll();
315: 
316:         return figNode;
317:     }
318: 
319: } /* end class ModeCreateAssociation */
