218: 		*/
219: 	private String GenerateDirectoriesPathname(MClassifier o, String path)
220: 	{
221:     String name = o.getName();
222:     if (name == null || name.length() == 0) return null;
223:     String filename = name + GetFileExtension();
224:     if (!path.endsWith (FILE_SEPARATOR)) path += FILE_SEPARATOR;
225: 
226:     String packagePath = o.getNamespace().getName();
227:     MNamespace parent = o.getNamespace().getNamespace();
228:     while (parent != null) {
229: 	  // ommit root package name; it's the model's root
230: 	  if (parent.getNamespace() != null)
231:         packagePath = parent.getName() + "." + packagePath;
232:       parent = parent.getNamespace();
233:     }
234: 
235: 	  int lastIndex=-1;
236:     do {
237:       File f = new File (path);
238:       if (!f.isDirectory()) {
239: 		    if (!f.mkdir()) {
240: 			    Argo.log.error(" could not make directory "+path);
241: 			    return null;
242: 		    }
243:       }
244: 
245: 	    if (lastIndex == packagePath.length())
246: 		    break;
247: 
248:       int index = packagePath.indexOf (".", lastIndex+1);
249: 	    if (index == -1)
250:   		  index = packagePath.length();
251: 
252:       path += packagePath.substring (lastIndex+1, index) + FILE_SEPARATOR;
253:       lastIndex = index;
254: 	  } while (true);
255: 
256:     String pathname = path + filename;
257: 		//Argo.log.info("-----" + pathname + "-----");
258: 		return pathname;
259: 	}
