265:      */
266:   public String GenerateFile(MClassifier o, String path) {
267:     String packagePath = o.getNamespace().getName();
268:    	String pathname = null;
269: 
270: 		// use unique section for both passes -> allow move of
271: 		// normal function body to inline and vice versa
272:    	sect = new Section();
273: 		/**
274: 		  * 2002-11-28 Achim Spangler
275: 			* first read header and source file into global/unique section
276: 			*/
277: 		for ( GeneratorPass = header_pass; GeneratorPass <= source_pass; GeneratorPass++ )
278: 		{
279: 			pathname = GenerateDirectoriesPathname(o, path);
280:     	//String pathname = path + filename;
281:     	// needs-more-work: package, project basepath, tagged values to configure
282:     	File f = new File(pathname);
283:     	if (f.exists()){
284:         	Argo.log.info("Generating (updated) " + f.getPath());
285:         	sect.read(pathname);
286:     	} else {
287:         	Argo.log.info("Generating (new) " + f.getPath());
288:     	}
289: 		}
290: 
291: 		/**
292: 		  * 2002-11-28 Achim Spangler
293: 			* run basic generation function two times for header and implementation
294: 			*/
295: 		for ( GeneratorPass = header_pass; GeneratorPass <= source_pass; GeneratorPass++ )
296: 		{
297: 			pathname = GenerateDirectoriesPathname(o, path);
298:     	//String pathname = path + filename;
299:     	// needs-more-work: package, project basepath, tagged values to configure
300:     	File f = new File(pathname);
301: 			String header_top = SINGLETON.generateHeaderTop(o, pathname, packagePath);
302:     	String header = SINGLETON.generateHeader (o, pathname, packagePath);
303:     	String src = SINGLETON.generate (o);
304:     	BufferedWriter fos = null;
305:     	try {
306:       	fos = new BufferedWriter (new FileWriter (f));
307: 				writeTemplate(o, path, fos );
308: 				fos.write( header_top );
309: 				fos.write( _ExtraIncludes );
310:       	fos.write (header);
311:       	fos.write (src);
312:     	}
313:     	catch (IOException exp) { }
314:     	finally {
315:       	try {
316:         	if (fos != null) fos.close();
317:       	}
318:       	catch (IOException exp) {
319:         	Argo.log.error("FAILED: " + f.getPath());
320:       	}
321:     	}
322: 
323: 			// clear extra includes after usage for each pass
324: 			_ExtraIncludes = "";
325: 			
326: 			// output lost sections only in the second path
327: 			// -> sections which are moved from header(inline) to source
328: 			// file are prevented to be outputted in header pass
329:     	if ( GeneratorPass == header_pass )	sect.write(pathname, INDENT, false);
330: 			else sect.write(pathname, INDENT, true);
331: 			
332:     	Argo.log.info("written: " + pathname);
333: 
334: 
335:     	File f1 = new File(pathname + ".bak");
336:     	if (f1.exists()){
337:         	f1.delete();
338:     	}
339: 
340:     	File f2 = new File(pathname);
341:     	if (f2.exists()){
342:         	f2.renameTo(new File(pathname + ".bak"));
343:     	}
344: 
345:     	File f3 = new File(pathname + ".out");
346:     	if (f3.exists()){
347:         	f3.renameTo(new File(pathname));
348:     	}
349: 
350:     	Argo.log.info("----- end updating -----");
351: 		}
352:    	return pathname;
353:   }
