384: 	private void writeTemplate( MClassifier cls, String path, BufferedWriter fos )
385: 	{
386: 		String TemplatePathName = path + "/templates/";
387: 		String FileName = cls.getName();
388: 		String TagTemplatePathName = cls.getTaggedValue( "TemplatePath" );
389: 		String AuthorTag = cls.getTaggedValue( "author" );
390: 		String EmailTag = cls.getTaggedValue( "email" );
391: 		if ( TagTemplatePathName != null && TagTemplatePathName.length() > 0 )
392: 			TemplatePathName = TagTemplatePathName;
393: 		if ( GeneratorPass == header_pass ) {
394: 			TemplatePathName = TemplatePathName + "header_template";
395: 			FileName = FileName + ".h";
396: 		}
397: 		else {
398: 			TemplatePathName = TemplatePathName + "cpp_template";
399: 			FileName = FileName + ".cpp";
400: 		}
401:     // Argo.log.info("Try to read Template: " + TemplatePathName);
402: 		File TemplateFile = new File( TemplatePathName );
403: 		if ( TemplateFile.exists())
404: 		{
405:     	boolean eof = false;
406:    		BufferedReader TemplateFileReader = null;
407:     	try {
408: 				TemplateFileReader = new BufferedReader(new FileReader(TemplateFile.getAbsolutePath()));
409:     		while (!eof){
410: 					String line_str = TemplateFileReader.readLine();
411:         	if (line_str == null) {
412:         		eof = true;
413:        		} else {
414: 	      		StringBuffer line = new StringBuffer(line_str);
415: 						int TokenStart = line.toString().indexOf( "|FILENAME|");
416: 						if ( TokenStart != -1) {
417: 							line.replace(TokenStart, (TokenStart + "|FILENAME|".length()), FileName);
418: 						}
419: 						TokenStart = line.toString().indexOf( "|DATE|");
420: 						if ( TokenStart != -1) {
421: 							line.replace(TokenStart, (TokenStart + "|DATE|".length()), getDate());
422: 						}
423: 						TokenStart = line.toString().indexOf( "|YEAR|");
424: 						if ( TokenStart != -1) {
425: 							line.replace(TokenStart, (TokenStart + "|YEAR|".length()), getYear());
426: 						}
427: 						TokenStart = line.toString().indexOf( "|AUTHOR|");
428: 						if ( ( TokenStart != -1) && ( AuthorTag != null && AuthorTag.length() > 0 )) {
429: 							line.replace(TokenStart, (TokenStart + "|AUTHOR|".length()), AuthorTag);
430: 						}
431: 						TokenStart = line.toString().indexOf( "|EMAIL|");
432: 						if ( ( TokenStart != -1) && ( EmailTag != null && EmailTag.length() > 0 )) {
433: 							line.replace(TokenStart, (TokenStart + "|EMAIL|".length()), EmailTag);
434: 						}
435: 
436:          		fos.write(line + "\n");
437:       		}
438:     		}
439:     		TemplateFileReader.close();
440: 			}
441:     	catch (IOException exp) { }
442:     	finally {
443:       	try {
444:         	if (TemplateFileReader != null) TemplateFileReader.close();
445:       	}
446:       	catch (IOException exp) {
447:         	Argo.log.error("FAILED: " + TemplateFile.getPath());
448:       	}
449:     	}
450: 		}
451: 	}
