785: 	private String generateNameWithPkgSelection( MModelElement item, MNamespace local_pkg ) {
786: 		if ( item == null ) {
787: 	    // Argo.log.info("generateNameWithPkgSelection: zu void" );
788: 			return "void ";
789: 		}
790:     // Argo.log.info("generateNameWithPkgSelection: " + item.getName() );
791: 		MNamespace pkg = null;
792: 		if ( item instanceof MDataType ) return generateName( item.getName() );
793: 		else if ( item instanceof MParameter ) pkg = ((MParameter)item).getNamespace();
794: 		else if ( item instanceof MAttribute ) pkg = ((MAttribute)item).getNamespace();
795: 		else if ( item instanceof MAssociationEnd ) pkg = ((MAssociationEnd)item).getNamespace();
796: 		else if ( item instanceof MClassifier ) pkg = ((MClassifier)item).getNamespace();
797: 
798: 		if ( pkg == null ) return generateName( item.getName() );
799: 		if (local_pkg == null ) 
800: 	    Argo.log.info("LOCAL NAMESPACE IS NULL" );
801: 			
802: 		String localPkgName = generatePackageAbsoluteName( local_pkg );
803: 		String targetPkgName = generatePackageAbsoluteName( pkg );
804:     // Argo.log.info("targetNamespace:" + targetPkgName + ":" );
805:     // Argo.log.info("localNamespace:" + localPkgName + ":" );
806: 		int localPkgNameLen = localPkgName.length();
807: 		int targetPkgNameLen = targetPkgName.length();
808: 		if ( localPkgName.equals( targetPkgName ) ) return generateName( item.getName() );
809: 		else {
810: 			if ( targetPkgName.indexOf( localPkgName ) != -1 ) {
811: 				/*
812: 				Argo.log.info("target is subpackage of local with |"
813: 					+ targetPkgName.substring(localPkgNameLen, localPkgNameLen+2 ) + "|");
814: 				*/
815: 				if (targetPkgName.substring(localPkgNameLen, localPkgNameLen+2 ).equals("::")) {
816: 					// target is in Sub-Package of local class
817: 					return (targetPkgName.substring(localPkgNameLen+2, targetPkgNameLen ) + "::" + generateName( item.getName() ));
818: 				}
819: 			}
820: 		}
821: 		return ( targetPkgName + "::" + generateName( item.getName() ));
822: 	}
