1053: 				 && (tag_type != SearchPointerTag)) return true;
1054:       	else if ((tag.indexOf("pointer") != -1 || tag.equals("*"))
1055: 				      && (tag_type != SearchReferenceTag)) return true;
1056:     	}
1057: 		}
1058: 		return false;
1059: 	}
