1751:   public String generateMethodBody (MOperation op) {
1752:     if (op != null) {
1753: 			StringBuffer sb = new StringBuffer(80);
1754:       Collection methods = op.getMethods();
1755:       Iterator i = methods.iterator();
1756:       MMethod m = null;
1757: 			boolean MethodFound = false;
