1765:       }
1766: 
1767: 			// place the curley braces within the protected area, to allow
1768: 			// placement of preserved contructor initialisers in this area
1769: 			// otherwise all possible constructor-attribute initialisers would have
1770: 			// to be autogenerated with an army of special tags
1771: 			sb.append( generateSectionTop(op, OperationIndent) )
1772: 			  .append( OperationIndent ).append( "{\n" );
