1780: 
1781:         if (m != null) {
1782:           //Argo.log.info(", BODY of "+m.getName());
1783:           //Argo.log.info("|"+m.getBody().getBody()+"|");
1784:           if (( m.getBody() != null) && ( !MethodFound ) ) {
1785:             sb.append( m.getBody().getBody() );
1786: 						MethodFound = true;
1787: 						break;
1788: 					}
1789:         }
1790:       }
1791: 
1792: 			if ( !MethodFound ) {
1793:       	// pick out return type as default method body
1794: 		    MParameter rp = UmlHelper.getHelper().getCore().getReturnParameter(op);
1795:       	if (rp != null) {
1796:         	MClassifier returnType = rp.getType();
1797:         	sb.append( generateDefaultReturnStatement (returnType) );
1798:       	}
1799: 			}
1800: 			sb.append( OperationIndent ).append( "}\n" )
1801: 		  	.append( generateSectionBottom(op, OperationIndent) );
1802: 			return sb.toString();
1803:     }
1804: 		return generateDefaultReturnStatement (null);
