2486:     StringBuffer sb = new StringBuffer(80);
2487: 		int countUpper = m.getUpper(),
2488: 		    countLower = m.getLower();
2489: 		// Argo.log.info("resolved int upper/lower bounds" );
2490:     Integer lower = new Integer(countLower);
2491:     Integer upper = new Integer(countUpper);
2492: 		// Argo.log.info("resolved Integer upper/lower bounds" );
2493: 
2494: 		if ( countUpper	== 1 ) {
2495: 			// simple generate identifier for default 0:1, 1:1 association
2496: 			sb.append( type ).append( ' ' ).append( modifier ).append( name );
2497: 		}
2498: 		else if ( countUpper == countLower ) {
