2513: 					_ExtraIncludes += "#include <vector>\n";
2514: 				container_type = "vector";
2515: 			}
2516: 			else if ( MultType.equals( "list" ) ) {
2517: 				if ( _ExtraIncludes.indexOf( "#include <list>" ) == -1 )
2518: 					_ExtraIncludes += "#include <list>\n";
2519: 				container_type = "list";
2520: 			}
2521: 			else if ( MultType.equals( "slist" ) ) {
2522: 				if ( _ExtraIncludes.indexOf( "#include <slist>" ) == -1 )
2523: 					_ExtraIncludes += "#include <slist>\n";
2524: 				container_type = "slist";
2525: 			}
2526: 			else if ( MultType.equals( "map" ) ) {
2527: 				if ( _ExtraIncludes.indexOf( "#include <map>" ) == -1 )
2528: 					_ExtraIncludes += "#include <map>\n";
2529: 				container_type = "map";
2530: 			}
2531: 			else if ( MultType.equals( "stack" ) ) {
2532: 				if ( _ExtraIncludes.indexOf( "#include <stack>" ) == -1 )
2533: 					_ExtraIncludes += "#include <stack>\n";
2534: 				container_type = "stack";
2535: 			}
2536: 			
2537: 			if ( container_type != null ) {
2538: 				// known container type
