41: /** Action to trigger creation of new collaboration diagram.
42:  *  @stereotype singleton
43:  */
44: public class ActionCollaborationDiagram extends ActionAddDiagram {
45: 
46:     public static ActionCollaborationDiagram SINGLETON = new ActionCollaborationDiagram();
47: 
48:     private ActionCollaborationDiagram() {
49:         super("action.collaboration-diagram");
50:     }
51: 
52:     /**
53:      * @see org.argouml.uml.ui.ActionAddDiagram#createDiagram(MNamespace,Object)
54:      */
55:     public UMLDiagram createDiagram(MNamespace handle) {
56:         Object target = ProjectBrowser.TheInstance.getTarget();
57:         MCollaboration c = null;
58:         if (target instanceof MOperation) {
59:             c = UmlFactory.getFactory().getCollaborations().buildCollaboration(handle);
60:             c.setRepresentedOperation((MOperation)target);
61:         } else
62:         if (target instanceof MClassifier) {
63:             c = UmlFactory.getFactory().getCollaborations().buildCollaboration((MClassifier)target);
64:             c.setRepresentedClassifier((MClassifier)target);
65:         } else
66:         if (target instanceof MModel) {
67:             c = UmlFactory.getFactory().getCollaborations().buildCollaboration((MModel)target);
68:         } else
69:         if (target instanceof MInteraction) {
70:             c = ((MInteraction)target).getContext();
71:         } else
72:         if (target instanceof UMLCollaborationDiagram) {
73:             Object o = ((UMLCollaborationDiagram)target).getOwner();
74:             if (o instanceof MCollaboration) { //preventing backward compat problems
75:                 c = (MCollaboration)o;
76:             }
77:         } else
78:         if (target instanceof MCollaboration) {
79:             c = (MCollaboration)target;
80:         } else {
81:             c =  UmlFactory.getFactory().getCollaborations().buildCollaboration(handle);
82:         }
83:         UMLCollaborationDiagram d  = new UMLCollaborationDiagram(c);
84:         return d;
85:     }
86: 
