88:      * @see org.argouml.model.uml.behavioralelements.collaborations.CollaborationsHelper#isAddingCollaborationAllowed(Object)
89:      * @see org.argouml.uml.ui.ActionAddDiagram#isValidNamespace(MNamespace)
90:      */
91:     public boolean isValidNamespace(MNamespace handle) {
92:         return CollaborationsHelper.getHelper().isAddingCollaborationAllowed(handle);
93:     }
94: 
95:     /**
96:      * Just calls isValidNamespace(...) on the nav pane target.
97:      * @see org.argouml.uml.ui.UMLAction#shouldBeEnabled()
98:      */
99:     public boolean shouldBeEnabled() {
100:         
101:         Object target = ProjectBrowser.TheInstance.getTarget();
102:         if(target instanceof MNamespace)
103:             return isValidNamespace((MNamespace)target);
104:         else
105:             return false;
106:     }
107:     
108: } /* end class ActionCollaborationDiagram */
