241:     /**
242:      * create the needed directories for the derived appropriate pathname
243:      * @return full pathname
244:      */
245:     private String generateDirectoriesPathname(MClassifier cls, String path)
246:     {
247: 	String name = cls.getName();
248: 	if (name == null || name.length() == 0) return null;
249: 	String filename = name + getFileExtension();
250: 	if (!path.endsWith (FILE_SEPARATOR)) path += FILE_SEPARATOR;
251: 
252:         String packagePath = "";
253:         // avoid model being used as a package name
254:         MNamespace parent = cls.getNamespace().getNamespace();
255:         if (parent != null) packagePath = cls.getNamespace().getName();
256: 	while (parent != null) {
257: 	    // ommit root package name; it's the model's root
258: 	    if (parent.getNamespace() != null)
259: 		packagePath = parent.getName() + "." + packagePath;
260: 	    parent = parent.getNamespace();
261: 	}
262: 
263: 	int lastIndex = -1;
264: 	do {
265: 	    File f = new File (path);
266: 	    if (!f.isDirectory()) {
267: 		if (!f.mkdir()) {
268: 		    LOG.error(" could not make directory " + path);
269: 		    return null;
270: 		}
271: 	    }
272: 
273: 	    if (lastIndex == packagePath.length())
274: 		break;
275: 
276: 	    int index = packagePath.indexOf (".", lastIndex + 1);
277: 	    if (index == -1)
278: 		index = packagePath.length();
279: 
280: 	    path +=
281: 		packagePath.substring (lastIndex + 1, index) + FILE_SEPARATOR;
282: 	    lastIndex = index;
283: 	} while (true);
284: 
285: 	String pathname = path + filename;
286: 	//cat.info("-----" + pathname + "-----");
287: 	return pathname;
288:     }
