479:     /**
480:      * Replace the first occurences of tokenName with tokenValue.
481:      *
482:      * @param line is the line where we do the replacing.
483:      * @param tokenName is the string we search for.
484:      * @param tokenValue is the value we replace.
485:      */
486:     private void replaceToken(StringBuffer line,
487: 			      String tokenName, String tokenValue) {
488:         int tokenStart;
489:         tokenStart = line.toString().indexOf(tokenName);
490: 	if ((tokenStart != -1)
491: 	    && (tokenValue != null && tokenValue.length() > 0)) {
492: 	    line.replace(tokenStart,
493: 			 tokenStart + tokenName.length(),
494: 			 tokenValue);
495: 	}
496:     }
