587:     private boolean checkIncludeNeeded4Element(MAssociation cls) {
588: 	String usageTag = "";
589: 	boolean result = false;
590: 	boolean predeclareCandidate = false;
591: 	Collection tValues = cls.getTaggedValues();
592: 	if (!tValues.isEmpty()) {
593: 	    Iterator iter = tValues.iterator();
594: 	    while (iter.hasNext()) {
595: 		MTaggedValue tv = (MTaggedValue) iter.next();
596: 		String tag = tv.getTag();
597: 		if (tag.equals("usage")) usageTag = tv.getValue();
598: 		// cat.info("Tag fuer: " + cls.getName() + " mit Tag:
599: 		// " + tag + " mit Wert:" + tv.getValue() + ":");
600: 
601: 		if (tag.indexOf("ref") != -1 || tag.equals("&")
602: 		    || tag.indexOf("pointer") != -1 || tag.equals("*"))
603: 		    predeclareCandidate = true;
604: 	    }
605: 	}
606: 	return checkInclude4UsageIndirection(predeclareCandidate, usageTag);
607:     }
