1100:     public String generateOperation(Object param, boolean documented) {
1101: 	MOperation op = (MOperation) param;
1102: 	// generate nothing for abstract functions, if we generate the
1103: 	// source .cpp file at the moment
1104: 	if ((generatorPass != header_pass) && (op.isAbstract())) {
