1110: 	// cat.info("generate Operation for File" + generatorPass + "
1111: 	// fuer Op: " + op.getName());
1112: 	boolean constructor =
1113: 	    SINGLETON.generateOperationNameAndTestForConstructor(op,
1114: 								 nameBuffer);
1115: 
1116: 	sb.append('\n'); // begin with a blank line
1117: 	// generate DocComment from tagged values
1118: 	String tv = generateTaggedValues (op, DocCommentTags);
1119: 	if (tv != null && tv.length() > 0) {
1120: 	    sb.append ("\n").append(operationIndent).append (tv);
1121: 	}
1122: 
1123: 	// 2002-07-14
1124: 	// Jaap Branderhorst
1125: 	// missing concurrency generation
1126: 	sb.append(operationIndent)
1127: 	    .append(SINGLETON.generateOperationPrefix(op));
1128: 
1129: 	// pick out return type
1130: 	MParameter rp = UmlHelper.getHelper().getCore().getReturnParameter(op);
1131: 	if (rp != null) {
1132: 	    MClassifier returnType = rp.getType();
1133: 	    if (returnType == null && !constructor) {
1134: 		sb.append("void ");
1135: 	    }
1136: 	    else if (returnType != null) {
1137: 		sb.append(generateNameWithPkgSelection(returnType)).append(' ');
1138: 	    }
1139: 	}
1140: 
1141: 	// name and params
1142: 	Vector params = new Vector (op.getParameters());
1143: 	params.remove (rp);
1144: 
1145: 	sb.append(nameBuffer.toString()).append('(');
1146: 
1147: 	if (params != null) {
1148: 	    boolean first = true;
1149: 
1150: 	    for (int i = 0; i < params.size(); i++) {
1151: 		MParameter p = (MParameter) params.elementAt (i);
1152: 
1153: 		if (!first) sb.append(", ");
1154: 
1155: 		sb.append(generateParameter(p));
1156: 		first = false;
1157: 	    }
1158: 	}
1159: 
1160: 	sb.append(") ")
1161: 	    .append(SINGLETON.generateOperationSuffix(op));
1162: 
1163: 	return sb.toString();
1164: 
