1196:     private String generateAttributeParameterModifier(MModelElement attr) {
1197: 	boolean isReference =
1198: 	    checkAttributeParameter4Tag(attr, SearchReferenceTag);
1199: 	boolean isPointer = checkAttributeParameter4Tag(attr, SearchPointerTag);
1200: 	StringBuffer sb = new StringBuffer(2);
1201: 
1202: 	if (isReference) sb.append("&");
1203: 	else if (isPointer) sb.append("*");
1204: 	else if (attr instanceof MParameter) {
1205: 	    if (((((MParameter) attr).getKind()).equals(MParameterDirectionKind.OUT))
1206: 		|| ((((MParameter) attr).getKind()).equals(MParameterDirectionKind.INOUT)))
1207: 	    { // out or inout parameters are defaulted to reference if
