1662: 	// "INDENT void set_<name>( const <type> &value ) { <name> = value; };"
1663: 	// generate for other (small) data types:
1664: 	// "INDENT void set_<name>( <type> value ) { <name> = value; };"
1665: 	// generate: "INDENT void set_<name>( "
1666: 	sb.append('\n').append(INDENT);
