1683: 	    sb.append("const ").append(generateClassifierRef(attr.getType()));
1684: 	    sb.append(" &value");
1685: 	} else {
1686: 	    // generate: "<type> value"
1687: 	    sb.append(generateClassifierRef(attr.getType()))
1688: 		.append(" value");
1689: 	}
1690: 	// generate: " ) { <name> = value; };"
1691: 	sb.append(" ) { ").append(attr.getName()).append(" = value; };");
