2380:     /**
2381:      * Enhance/Create the doccomment for the given model element,
2382:      * including tags for any OCL constraints connected to the model
2383:      * element. The tags generated are suitable for use with the ocl
2384:      * injector which is part of the Dresden OCL Toolkit and are in
2385:      * detail:
2386:      *
2387:      * &nbsp;@invariant for each invariant specified
2388:      * &nbsp;@precondition for each precondition specified
2389:      * &nbsp;@postcondition for each postcondition specified
2390:      * &nbsp;@key-type specifying the class of the keys of a mapped association
2391:      * &nbsp; Currently mapped associations are not supported yet...
2392:      * &nbsp;@element-type specifying the class referenced in an association
2393:      *
2394:      * @since 2001-09-26 ArgoUML 0.9.3
2395:      * @author Steffen Zschaler
2396:      *
2397:      * @param me the model element for which the documentation comment is needed
2398:      * @param ae the association end which is represented by the model element
2399:      * @return the documentation comment for the specified model element, either
2400:      * enhanced or completely generated
2401:      */
2402:     public String generateConstraintEnrichedDocComment (MModelElement me,
2403: 							MAssociationEnd ae) {
2404: 	// list tagged values for documentation
2405: 	String s = generateTaggedValues (me, DocCommentTags);
2406: 
2407: 
2408: 	MMultiplicity m = ae.getMultiplicity();
2409: 	if (!(MMultiplicity.M1_1.equals(m) || MMultiplicity.M0_1.equals (m))) {
2410: 	    // Multiplicity greater 1, that means we will generate some sort of
2411: 	    // collection, so we need to specify the element type tag
2412: 	    StringBuffer sDocComment = new StringBuffer(80);
2413: 
2414: 	    // Prepare doccomment
2415: 	    if (!(s == null || "".equals(s))) {
2416: 		// Just remove closing "*/"
2417: 		sDocComment.append(s.substring(0, s.indexOf("*/") + 1));
2418: 	    }
2419: 	    else {
2420: 		sDocComment.append(INDENT).append("/**\n");
2421: 		sDocComment.append(INDENT).append(" * \n");
2422: 		sDocComment.append(INDENT).append(" *");
2423: 	    }
2424: 
2425: 	    // Build doccomment
2426: 	    MClassifier type = ae.getType();
2427: 	    if (type != null) {
2428: 		sDocComment.append(" @element-type ").append(type.getName());
2429: 	    } else {
2430: 		// REMOVED: 2002-03-11 STEFFEN ZSCHALER: element type
2431: 		// unknown is not recognized by the OCL injector...
2432: 		//sDocComment += " @element-type unknown";
2433: 	    }
2434: 	    sDocComment.append('\n').append(INDENT).append(" */\n");
2435: 	    return sDocComment.toString();
2436: 	}
2437: 	else {
2438: 	    return (s != null) ? s : "";
2439: 	}
2440:     }
