239:     /**
240:      * create the needed directories for the derived appropriate pathname
241:      * @return full pathname
242:      */
243:     private String generateDirectoriesPathname(MClassifier cls, String path)
244:     {
245: 	String name = cls.getName();
246: 	if (name == null || name.length() == 0) return null;
247: 	String filename = name + getFileExtension();
248: 	if (!path.endsWith (FILE_SEPARATOR)) path += FILE_SEPARATOR;
249: 
250:         String packagePath = "";
251:         // avoid model being used as a package name
252:         MNamespace parent = cls.getNamespace().getNamespace();
253:         if (parent != null) packagePath = cls.getNamespace().getName();
254: 	while (parent != null) {
255: 	    // ommit root package name; it's the model's root
256: 	    if (parent.getNamespace() != null)
257: 		packagePath = parent.getName() + "." + packagePath;
258: 	    parent = parent.getNamespace();
259: 	}
260: 
261: 	int lastIndex = -1;
262: 	do {
263: 	    File f = new File (path);
264: 	    if (!f.isDirectory()) {
265: 		if (!f.mkdir()) {
266: 		    LOG.error(" could not make directory " + path);
267: 		    return null;
268: 		}
269: 	    }
270: 
271: 	    if (lastIndex == packagePath.length())
272: 		break;
273: 
274: 	    int index = packagePath.indexOf (".", lastIndex + 1);
275: 	    if (index == -1)
276: 		index = packagePath.length();
277: 
278: 	    path +=
279: 		packagePath.substring (lastIndex + 1, index) + FILE_SEPARATOR;
280: 	    lastIndex = index;
281: 	} while (true);
282: 
283: 	String pathname = path + filename;
284: 	//cat.info("-----" + pathname + "-----");
285: 	return pathname;
286:     }
