288:     /**
289:      * Generates a file for the classifier.
290:      * This method could have been static if it where not for the need to
291:      * call it through the Generatorinterface.<p>
292:      *
293:      * @return the full path name of the the generated file.
294:      * @see FileGenerator#GenerateFile(Object, String)
295:      */
296:     public String GenerateFile(Object o, String path) {
297: 	MClassifier cls = (MClassifier) o;
298: 	String packagePath = cls.getNamespace().getName();
299:    	String pathname = null;
300: 
301: 	// use unique section for both passes -> allow move of
302: 	// normal function body to inline and vice versa
303:    	sect = new Section();
304: 
305: 	/*
306: 	 * 2002-11-28 Achim Spangler
307: 	 * first read header and source file into global/unique section
308: 	 */
309: 	for (generatorPass = header_pass;
310: 	     generatorPass <= source_pass;
311: 	     generatorPass++) {
312: 	    pathname = generateDirectoriesPathname(cls, path);
313: 	    //String pathname = path + filename;
314: 	    // TODO: package, project basepath, tagged values to configure
315: 	    File f = new File(pathname);
316: 	    if (f.exists()) {
317: 		LOG.info("Generating (updated) " + f.getPath());
318: 		sect.read(pathname);
319: 	    } else {
320: 		LOG.info("Generating (new) " + f.getPath());
321: 	    }
322: 	}
323: 
324: 	/**
325: 	 * 2002-11-28 Achim Spangler
326: 	 * run basic generation function two times for header and implementation
327: 	 */
328: 	for (generatorPass = header_pass;
329: 	     generatorPass <= source_pass;
330: 	     generatorPass++) {
331: 	    pathname = generateDirectoriesPathname(cls, path);
332: 	    //String pathname = path + filename;
333: 	    // TODO: package, project basepath, tagged values to configure
334: 	    File f = new File(pathname);
335: 	    String headerTop =
336: 		SINGLETON.generateHeaderTop(cls, pathname, packagePath);
337: 	    String header =
338: 		SINGLETON.generateHeader (cls, pathname, packagePath);
339: 	    String src = SINGLETON.generate (cls);
340: 	    BufferedWriter fos = null;
341: 	    try {
342: 		fos = new BufferedWriter (new FileWriter (f));
343: 		writeTemplate(cls, path, fos);
344: 		fos.write(headerTop);
345: 		fos.write(extraIncludes);
346: 		fos.write (header);
347: 		fos.write (src);
348: 	    }
349: 	    catch (IOException exp) { }
350: 	    finally {
351: 		try {
352: 		    if (fos != null) fos.close();
353: 		}
354: 		catch (IOException exp) {
355: 		    LOG.error("FAILED: " + f.getPath());
356: 		}
357: 	    }
358: 
359: 	    // clear extra includes after usage for each pass
360: 	    extraIncludes = "";
361: 
362: 	    // output lost sections only in the second path
363: 	    // -> sections which are moved from header(inline) to source
364: 	    // file are prevented to be outputted in header pass
365: 	    if (generatorPass == header_pass)	{
366: 		sect.write(pathname, INDENT, false);
367: 	    }
368: 	    else sect.write(pathname, INDENT, true);
369: 
370: 	    LOG.info("written: " + pathname);
371: 
372: 
373: 	    File f1 = new File(pathname + ".bak");
374: 	    if (f1.exists()) {
375: 		f1.delete();
376: 	    }
377: 
378: 	    File f2 = new File(pathname);
379: 	    if (f2.exists()) {
380: 		f2.renameTo(new File(pathname + ".bak"));
381: 	    }
382: 
383: 	    File f3 = new File(pathname + ".out");
384: 	    if (f3.exists()) {
385: 		f3.renameTo(new File(pathname));
386: 	    }
387: 
388: 	    LOG.info("----- end updating -----");
389: 	}
390:    	return pathname;
391:     }
