909: 		*/
910: 		if (targetPkgName.substring(localPkgNameLen,
911: 					    localPkgNameLen + 2)
912: 		    .equals("::")) {
913: 		    // target is in Sub-Package of local class
914: 		    return (targetPkgName.substring(localPkgNameLen + 2,
