1593: 		MAssociationEnd ae = (MAssociationEnd) endEnum.next();
1594: 		MAssociation a = ae.getAssociation();
1595: 		MVisibilityKind vis = ae.getVisibility();
1596: 		if (((publicProtectedPrivate == PUBLIC_PART)
1597: 		     && (MVisibilityKind.PUBLIC.equals(vis)))
1598: 		    || ((publicProtectedPrivate == PROTECTED_PART)
1599: 			&& (MVisibilityKind.PROTECTED.equals(vis)))
1600: 		    || ((publicProtectedPrivate == PRIVATE_PART)
1601: 			&& (MVisibilityKind.PRIVATE.equals(vis)))) {
1602: 		    if (!isVisibilityLinePrinted) {
1603: 			isVisibilityLinePrinted = true;
1604: 			if (publicProtectedPrivate == PUBLIC_PART) {
1605: 			    sb.append("\n public:");
1606: 			} else if (publicProtectedPrivate == PROTECTED_PART) {
1607: 			    sb.append("\n protected:");
1608: 			} else if (publicProtectedPrivate == PRIVATE_PART) {
1609: 			    sb.append("\n private:");
1610: 			}
1611: 		    }
1612: 
1613: 		    sb.append(generateAssociationFrom(a, ae));
1614: 
1615: 		    tv = generateTaggedValues(a, AllButDocTags);
1616: 		    if (tv != null && tv.length() > 0)
1617: 		    {
1618: 			sb.append(INDENT).append(tv);
1619: 		    }
1620: 		}
1621: 	    }
