1625:     /**
1626:      * Check whether an operation body shall be generated within the actual
1627:      * pass. This is normally done during the imeplementation path.
1628:      * But if the Tag "inline" exists, the method body shall be defined as
1629:      * as inline in header file
1630:      * @return true -> generate body in actual path
1631:      */
1632:     private boolean checkGenerateOperationBody(MOperation cls)
1633:     {
1634:         boolean result =
1635:             !((generatorPass == header_pass) || (cls.isAbstract()) || 
1636:             ModelFacade.isAInterface(cls.getOwner()));
1637: 
1638: 	// if this operation has Tag "inline" the method shall be
1639: 	// generated in header
1640: 	Collection tValues = cls.getTaggedValues();
1641: 	if (!tValues.isEmpty()) {
1642: 	    Iterator iter = tValues.iterator();
1643: 	    while (iter.hasNext()) {
1644: 		MTaggedValue tv = (MTaggedValue) iter.next();
1645: 		String tag = tv.getTag();
1646: 		if (tag.equals("inline")) {
1647: 		    result = (generatorPass == header_pass) ? true : false;
1648: 		}
1649: 	    }
1650: 	}
1651: 	return result;
1652:     }
