1654:     /** 2002-12-13 Achim Spangler
1655:      * generate a single set function for a given attribute and StringBuffer
1656:      */
1657:     private void generateSingleAttributeSet(MAttribute attr, StringBuffer sb) {
1658: 	if (attr.getType() == null) return;
1659: 	// generate for attributes with class-type:
1660: 	// "INDENT void set_<name>( const <type> &value ) { <name> = value; };"
1661: 	// generate for other (small) data types:
1662: 	// "INDENT void set_<name>( <type> value ) { <name> = value; };"
1663: 	// generate: "INDENT void set_<name>( "
1664: 	sb.append('\n').append(INDENT);
1665: 	sb.append("/** simple access function to set the attribute ");
1666: 	sb.append(attr.getName());
1667: 	sb.append(" by function\n").append(INDENT);
1668: 	sb.append("  * @param value value to set for the attribute ");
1669: 	sb.append(attr.getName()).append("\n").append(INDENT).append("  */\n");
1670: 	sb.append(INDENT);
1671: 	sb.append("void set_").append(attr.getName()).append("( ");
1672: 	String modifier = generateAttributeParameterModifier(attr);
1673: 	if (modifier != null && modifier.length() > 0) {
1674: 	    // generate: "const <type> <modifier>value"
1675: 	    if (modifier.equals("&")) sb.append("const ");
1676: 	    sb.append(generateClassifierRef(attr.getType()))
1677: 		.append(' ').append(modifier).append("value");
1678: 	}
1679: 	else if (attr.getType() instanceof MClass) {
1680: 	    // generate: "const <type> &value"
1681: 	    sb.append("const ").append(generateClassifierRef(attr.getType()));
1682: 	    sb.append(" &value");
1683: 	} else {
1684: 	    // generate: "<type> value"
1685: 	    sb.append(generateClassifierRef(attr.getType()))
1686: 		.append(" value");
1687: 	}
1688: 	// generate: " ) { <name> = value; };"
1689: 	sb.append(" ) { ").append(attr.getName()).append(" = value; };");
1690:     }
