1985:     /**
1986:      * Generate the body of a method associated with the given
1987:      * operation.  This assumes there's at most one method associated!
1988:      *
1989:      * If no method is associated with the operation, a default method
1990:      * body will be generated.
1991:      */
1992:     public String generateMethodBody (MOperation op) {
1993: 	if (op != null) {
1994: 	    StringBuffer sb = new StringBuffer(80);
1995: 	    Collection methods = op.getMethods();
1996: 	    Iterator i = methods.iterator();
1997: 	    MMethod m = null;
1998: 	    boolean methodFound = false;
1999: 	    String tv = generateTaggedValues(op, AllButDocTags);
2000: 	    String operationIndent =
2001: 		(generatorPass == header_pass) ? INDENT : "";
2002: 
2003: 	    // append tags which are not Doc-Comments
2004: 	    if (tv.length() > 0)
2005: 	    {
2006: 		sb.append(operationIndent).append(tv).append('\n');
2007: 	    }
2008: 
2009: 	    // place the curley braces within the protected area, to
2010: 	    // allow placement of preserved contructor initialisers in
2011: 	    // this area otherwise all possible constructor-attribute
2012: 	    // initialisers would have to be autogenerated with an
2013: 	    // army of special tags
2014: 	    sb.append(generateSectionTop(op, operationIndent))
2015: 		.append(operationIndent).append("{\n");
2016: 
2017: 	    // System.out.print(", op!=null, size="+methods.size());
2018: 	    // return INDENT + INDENT
2019: 	    // + "/* method body for " + op.getName() + " */";
2020: 
2021: 	    while (i != null && i.hasNext()) {
2022: 		//System.out.print(", i!= null");
2023: 		m = (MMethod) i.next();
2024: 
2025: 		if (m != null) {
2026: 		    //cat.info(", BODY of "+m.getName());
2027: 		    //cat.info("|"+m.getBody().getBody()+"|");
2028: 		    if ((m.getBody() != null) && (!methodFound)) {
2029: 			sb.append(m.getBody().getBody());
2030: 			methodFound = true;
2031: 			break;
2032: 		    }
2033: 		}
2034: 	    }
2035: 
2036: 	    if (!methodFound) {
2037: 		// pick out return type as default method body
2038: 		MParameter rp =
2039: 		    UmlHelper.getHelper().getCore().getReturnParameter(op);
2040: 		if (rp != null) {
2041: 		    MClassifier returnType = rp.getType();
2042: 		    sb.append(generateDefaultReturnStatement (returnType));
2043: 		}
2044: 	    }
2045: 	    sb.append(operationIndent).append("}\n")
2046: 		.append(generateSectionBottom(op, operationIndent));
2047: 	    return sb.toString();
2048: 	}
2049: 	return generateDefaultReturnStatement (null);
2050:     }
