2378:     /**
2379:      * Enhance/Create the doccomment for the given model element,
2380:      * including tags for any OCL constraints connected to the model
2381:      * element. The tags generated are suitable for use with the ocl
2382:      * injector which is part of the Dresden OCL Toolkit and are in
2383:      * detail:
2384:      *
2385:      * &nbsp;@invariant for each invariant specified
2386:      * &nbsp;@precondition for each precondition specified
2387:      * &nbsp;@postcondition for each postcondition specified
2388:      * &nbsp;@key-type specifying the class of the keys of a mapped association
2389:      * &nbsp; Currently mapped associations are not supported yet...
2390:      * &nbsp;@element-type specifying the class referenced in an association
2391:      *
2392:      * @since 2001-09-26 ArgoUML 0.9.3
2393:      * @author Steffen Zschaler
2394:      *
2395:      * @param me the model element for which the documentation comment is needed
2396:      * @param ae the association end which is represented by the model element
2397:      * @return the documentation comment for the specified model element, either
2398:      * enhanced or completely generated
2399:      */
2400:     public String generateConstraintEnrichedDocComment (MModelElement me,
2401: 							MAssociationEnd ae) {
2402: 	// list tagged values for documentation
2403: 	String s = generateTaggedValues (me, DocCommentTags);
2404: 
2405: 
2406: 	MMultiplicity m = ae.getMultiplicity();
2407: 	if (!(MMultiplicity.M1_1.equals(m) || MMultiplicity.M0_1.equals (m))) {
2408: 	    // Multiplicity greater 1, that means we will generate some sort of
2409: 	    // collection, so we need to specify the element type tag
2410: 	    StringBuffer sDocComment = new StringBuffer(80);
2411: 
2412: 	    // Prepare doccomment
2413: 	    if (!(s == null || "".equals(s))) {
2414: 		// Just remove closing "*/"
2415: 		sDocComment.append(s.substring(0, s.indexOf("*/") + 1));
2416: 	    }
2417: 	    else {
2418: 		sDocComment.append(INDENT).append("/**\n");
2419: 		sDocComment.append(INDENT).append(" * \n");
2420: 		sDocComment.append(INDENT).append(" *");
2421: 	    }
2422: 
2423: 	    // Build doccomment
2424: 	    MClassifier type = ae.getType();
2425: 	    if (type != null) {
2426: 		sDocComment.append(" @element-type ").append(type.getName());
2427: 	    } else {
2428: 		// REMOVED: 2002-03-11 STEFFEN ZSCHALER: element type
2429: 		// unknown is not recognized by the OCL injector...
2430: 		//sDocComment += " @element-type unknown";
2431: 	    }
2432: 	    sDocComment.append('\n').append(INDENT).append(" */\n");
2433: 	    return sDocComment.toString();
2434: 	}
2435: 	else {
2436: 	    return (s != null) ? s : "";
2437: 	}
2438:     }
