2749:     public String generateMultiplicity(Object handle) {
2750: 	MMultiplicity m = (MMultiplicity)handle;
2751: 	if (m == null) { return ""; }
2752: 	if (MMultiplicity.M0_N.equals(m)) return ANY_RANGE;
2753: 	String s = "";
2754: 	Collection v = m.getRanges();
2755: 	if (v == null) return s;
2756: 	Iterator rangeEnum = v.iterator();
2757: 	while (rangeEnum.hasNext()) {
2758: 	    MMultiplicityRange mr = (MMultiplicityRange) rangeEnum.next();
2759: 	    s += generateMultiplicityRange(mr);
2760: 	    if (rangeEnum.hasNext()) s += ",";
2761: 	}
2762: 	return s;
2763:     }
