290:     /**
291:      * Generates a file for the classifier.
292:      * This method could have been static if it where not for the need to
293:      * call it through the Generatorinterface.<p>
294:      *
295:      * @return the full path name of the the generated file.
296:      * @see FileGenerator#GenerateFile(Object, String)
297:      */
298:     public String GenerateFile(Object o, String path) {
299: 	MClassifier cls = (MClassifier) o;
300: 	String packagePath = cls.getNamespace().getName();
301:    	String pathname = null;
302: 
303: 	// use unique section for both passes -> allow move of
304: 	// normal function body to inline and vice versa
305:    	sect = new Section();
306: 
307: 	/*
308: 	 * 2002-11-28 Achim Spangler
309: 	 * first read header and source file into global/unique section
310: 	 */
311: 	for (generatorPass = header_pass;
312: 	     generatorPass <= source_pass;
313: 	     generatorPass++) {
314: 	    pathname = generateDirectoriesPathname(cls, path);
315: 	    //String pathname = path + filename;
316: 	    // TODO: package, project basepath, tagged values to configure
317: 	    File f = new File(pathname);
318: 	    if (f.exists()) {
319: 		LOG.info("Generating (updated) " + f.getPath());
320: 		sect.read(pathname);
321: 	    } else {
322: 		LOG.info("Generating (new) " + f.getPath());
323: 	    }
324: 	}
325: 
326: 	/**
327: 	 * 2002-11-28 Achim Spangler
328: 	 * run basic generation function two times for header and implementation
329: 	 */
330: 	for (generatorPass = header_pass;
331: 	     generatorPass <= source_pass;
332: 	     generatorPass++) {
333: 	    pathname = generateDirectoriesPathname(cls, path);
334: 	    //String pathname = path + filename;
335: 	    // TODO: package, project basepath, tagged values to configure
336: 	    File f = new File(pathname);
337: 	    String headerTop =
338: 		SINGLETON.generateHeaderTop(cls, pathname, packagePath);
339: 	    String header =
340: 		SINGLETON.generateHeader (cls, pathname, packagePath);
341: 	    String src = SINGLETON.generate (cls);
342: 	    BufferedWriter fos = null;
343: 	    try {
344: 		fos = new BufferedWriter (new FileWriter (f));
345: 		writeTemplate(cls, path, fos);
346: 		fos.write(headerTop);
347: 		fos.write(extraIncludes);
348: 		fos.write (header);
349: 		fos.write (src);
350: 	    }
351: 	    catch (IOException exp) { }
352: 	    finally {
353: 		try {
354: 		    if (fos != null) fos.close();
355: 		}
356: 		catch (IOException exp) {
357: 		    LOG.error("FAILED: " + f.getPath());
358: 		}
359: 	    }
360: 
361: 	    // clear extra includes after usage for each pass
362: 	    extraIncludes = "";
363: 
364: 	    // output lost sections only in the second path
365: 	    // -> sections which are moved from header(inline) to source
366: 	    // file are prevented to be outputted in header pass
367: 	    if (generatorPass == header_pass)	{
368: 		sect.write(pathname, INDENT, false);
369: 	    }
370: 	    else sect.write(pathname, INDENT, true);
371: 
372: 	    LOG.info("written: " + pathname);
373: 
374: 
375: 	    File f1 = new File(pathname + ".bak");
376: 	    if (f1.exists()) {
377: 		f1.delete();
378: 	    }
379: 
380: 	    File f2 = new File(pathname);
381: 	    if (f2.exists()) {
382: 		f2.renameTo(new File(pathname + ".bak"));
383: 	    }
384: 
385: 	    File f3 = new File(pathname + ".out");
386: 	    if (f3.exists()) {
387: 		f3.renameTo(new File(pathname));
388: 	    }
389: 
390: 	    LOG.info("----- end updating -----");
391: 	}
392:    	return pathname;
393:     }
