431: 	if (tagTemplatePathName != null && tagTemplatePathName.length() > 0)
432: 	    templatePathName = tagTemplatePathName;
433: 	if (generatorPass == header_pass) {
434: 	    templatePathName = templatePathName + "header_template";
435: 	    fileName = fileName + ".h";
436: 	}
437: 	else {
438: 	    templatePathName = templatePathName + "cpp_template";
439: 	    fileName = fileName + ".cpp";
440: 	}
441: 	// cat.info("Try to read Template: " + templatePathName);
442: 	File templateFile = new File(templatePathName);
443: 	if (templateFile.exists())
444: 	{
445: 	    boolean eof = false;
446: 	    BufferedReader templateFileReader = null;
447: 	    try {
448: 		templateFileReader =
449: 		    new BufferedReader(new FileReader(templateFile.getAbsolutePath()));
450: 		while (!eof) {
451: 		    String lineStr = templateFileReader.readLine();
452: 		    if (lineStr == null) {
453: 			eof = true;
454: 		    } else {
455: 			StringBuffer line = new StringBuffer(lineStr);
456:                         replaceToken(line, "|FILENAME|", fileName);
457:                         replaceToken(line, "|DATE|", getDate());
458:                         replaceToken(line, "|YEAR|", getYear());
459:                         replaceToken(line, "|AUTHOR|", authorTag);
460:                         replaceToken(line, "|EMAIL|", emailTag);
461: 
462: 			fos.write(line + "\n");
463: 		    }
464: 		}
465: 		templateFileReader.close();
466: 	    }
467: 	    catch (IOException exp) { }
468: 	    finally {
469: 		try {
470: 		    if (templateFileReader != null) templateFileReader.close();
471: 		}
472: 		catch (IOException exp) {
473: 		    LOG.error("FAILED: " + templateFile.getPath());
474: 		}
475: 	    }
476: 	}
477:     }
