1036: 	    // make all operations to virtual - as long as they are not "leaf"
1037: 	    MScopeKind scope = op.getOwnerScope();
1038: 	    // generate a function as virtual, if it can be overriden
1039: 	    // or override another function AND if this function is
1040: 	    // not marked as static, which disallows "virtual"
1041: 	    // alternatively every abstract function is defined as
1042: 	    // virtual
1043: 	    if ((!op.isLeaf()
1044: 		 && !op.isRoot()
1045: 		 && (!(MScopeKind.CLASSIFIER.equals(scope))))
1046: 		|| (op.isAbstract())) {
1047: 		sb.append("virtual ");
1048: 	    }
1049: 	    sb.append(generateScope(op));
1050: 	}
1051: 	return sb.toString();
1052:     }
