1174:     private boolean checkAttributeParameter4Tag(MModelElement elem,
1175: 						int tagType) {
1176: 	// first check whether the parameter shall be a pointer of reference
1177:   	Collection tValues = elem.getTaggedValues();
1178:   	if (!tValues.isEmpty()) {
1179: 	    Iterator iter = tValues.iterator();
1180: 	    while (iter.hasNext()) {
1181: 		MTaggedValue tv = (MTaggedValue) iter.next();
1182: 		String tag = tv.getTag();
1183: 		if ((tag.indexOf("ref") != -1 || tag.equals("&"))
1184: 		    && (tagType != SearchPointerTag)) {
1185: 		    return true;
1186: 		} else if ((tag.indexOf("pointer") != -1 || tag.equals("*"))
1187: 			   && (tagType != SearchReferenceTag)) {
1188: 		    return true;
1189: 		}
1190: 	    }
1191: 	}
1192: 	return false;
1193:     }
