1338:      *
1339:      * @return the generated start sequence
1340:      */
1341:     StringBuffer generateClassifierStart (MClassifier cls) {
1342: 	StringBuffer sb = new StringBuffer (80);
1343: 
1344: 	// don't create class-Start for implementation in .cpp
1345: 	if (generatorPass != header_pass) return sb;
1346: 
1347: 	String sClassifierKeyword;
1348: 	if (cls instanceof MClass) sClassifierKeyword = "class";
1349: 	else if (cls instanceof MInterface) sClassifierKeyword = "class";
1350: 	else return null; // actors, use cases etc.
1351: 	boolean hasBaseClass = false;
1352: 
1353: 	// Add the comments for this classifier first.
1354: 	sb.append ('\n')
1355: 	    .append (DocumentationManager.getComments(cls));
1356: 
1357: 	// list tagged values for documentation
1358: 	String tv = generateTaggedValues (cls, DocCommentTags);
1359: 	if (tv != null && tv.length() > 0) {
1360: 	    sb.append ("\n").append (INDENT).append (tv);
1361: 	}
1362: 
1363: 	// add classifier keyword and classifier name
1364: 	sb.append(sClassifierKeyword).append(" ");
1365: 	sb.append(generateName (cls.getName()));
1366: 
1367: 	// add base class/interface
1368: 	String baseClass = generateGeneralization (cls.getGeneralizations());
1369: 	if (!baseClass.equals ("")) {
1370: 	    sb.append (" : ")
1371: 		.append (baseClass);
1372: 	    hasBaseClass = true;
1373: 	}
1374: 
1375: 	// add implemented interfaces, if needed
1376: 	// nsuml: realizations!
1377: 	if (cls instanceof MClass) {
1378: 	    String interfaces = generateSpecification ((MClass) cls);
1379: 	    if (!interfaces.equals ("")) {
1380: 		if (!hasBaseClass) sb.append (" : ");
