1670: 	sb.append("  * @param value value to set for the attribute ");
1671: 	sb.append(attr.getName()).append("\n").append(INDENT).append("  */\n");
1672: 	sb.append(INDENT);
1673: 	sb.append("void set_").append(attr.getName()).append("( ");
1674: 	String modifier = generateAttributeParameterModifier(attr);
1675: 	if (modifier != null && modifier.length() > 0) {
1676: 	    // generate: "const <type> <modifier>value"
