1994:     public String generateMethodBody (MOperation op) {
1995: 	if (op != null) {
1996: 	    StringBuffer sb = new StringBuffer(80);
1997: 	    Collection methods = op.getMethods();
1998: 	    Iterator i = methods.iterator();
1999: 	    MMethod m = null;
2000: 	    boolean methodFound = false;
2001: 	    String tv = generateTaggedValues(op, AllButDocTags);
2002: 	    String operationIndent =
2003: 		(generatorPass == header_pass) ? INDENT : "";
2004: 
2005: 	    // append tags which are not Doc-Comments
2006: 	    if (tv.length() > 0)
2007: 	    {
2008: 		sb.append(operationIndent).append(tv).append('\n');
2009: 	    }
2010: 
2011: 	    // place the curley braces within the protected area, to
2012: 	    // allow placement of preserved contructor initialisers in
2013: 	    // this area otherwise all possible constructor-attribute
2014: 	    // initialisers would have to be autogenerated with an
2015: 	    // army of special tags
2016: 	    sb.append(generateSectionTop(op, operationIndent))
2017: 		.append(operationIndent).append("{\n");
2018: 
2019: 	    // System.out.print(", op!=null, size="+methods.size());
2020: 	    // return INDENT + INDENT
2021: 	    // + "/* method body for " + op.getName() + " */";
2022: 
2023: 	    while (i != null && i.hasNext()) {
2024: 		//System.out.print(", i!= null");
2025: 		m = (MMethod) i.next();
2026: 
2027: 		if (m != null) {
2028: 		    //cat.info(", BODY of "+m.getName());
2029: 		    //cat.info("|"+m.getBody().getBody()+"|");
2030: 		    if ((m.getBody() != null) && (!methodFound)) {
2031: 			sb.append(m.getBody().getBody());
2032: 			methodFound = true;
2033: 			break;
2034: 		    }
2035: 		}
2036: 	    }
2037: 
2038: 	    if (!methodFound) {
2039: 		// pick out return type as default method body
2040: 		MParameter rp =
2041: 		    UmlHelper.getHelper().getCore().getReturnParameter(op);
2042: 		if (rp != null) {
2043: 		    MClassifier returnType = rp.getType();
2044: 		    sb.append(generateDefaultReturnStatement (returnType));
2045: 		}
2046: 	    }
2047: 	    sb.append(operationIndent).append("}\n")
2048: 		.append(generateSectionBottom(op, operationIndent));
2049: 	    return sb.toString();
2050: 	}
2051: 	return generateDefaultReturnStatement (null);
2052:     }
