2430: 		// REMOVED: 2002-03-11 STEFFEN ZSCHALER: element type
2431: 		// unknown is not recognized by the OCL injector...
2432: 		//sDocComment += " @element-type unknown";
2433: 	    }
2434: 	    sDocComment.append('\n').append(INDENT).append(" */\n");
2435: 	    return sDocComment.toString();
2436: 	}
2437: 	else {
2438: 	    return (s != null) ? s : "";
2439: 	}
