2767:     public String generateMultiplicity(MModelElement item, String name,
2768: 				       MMultiplicity m, String modifier) {
2769: 	String type = null;
2770: 	String containerType = null;
2771: 	// cat.info("generateMultiplicity mit item" + item.getName() +
2772: 	// ", name: " + name + ", modifier: " + modifier);
2773: 
2774: 	MClassifier typeCls = null;
2775: 	if (item instanceof MAssociationEnd) {
2776: 	    typeCls = ((MAssociationEnd) item).getType();
2777: 	} else if (item instanceof MAttribute) {
2778: 	    typeCls = ((MAttribute) item).getType();
2779: 	} else if (item instanceof MClassifier) {
2780: 	    type = ((MClassifier) item).getName();
2781: 	} else {
2782: 	    type = "";
2783: 	}
2784: 	if (typeCls != null) type = generateNameWithPkgSelection(typeCls);
2785: 	// cat.info("resolved type_name: " + type);
2786: 	if (m == null) { return (type + " " + modifier + name); }
2787: 	StringBuffer sb = new StringBuffer(80);
2788: 	int countUpper = m.getUpper(),
2789: 	    countLower = m.getLower();
2790: 	// cat.info("resolved int upper/lower bounds");
2791: 	Integer lower = new Integer(countLower);
2792: 	Integer upper = new Integer(countUpper);
2793: 	// cat.info("resolved Integer upper/lower bounds");
2794: 
2795: 	if (countUpper	== 1) {
2796: 	    // simple generate identifier for default 0:1, 1:1 association
2797: 	    sb.append(type).append(' ').append(modifier).append(name);
2798: 	}
2799: 	else if (countUpper == countLower) {
2800: 	    // fixed array -> <type> <name>[<count>];
2801: 	    sb.append(type).append(' ').append(modifier).append(name)
2802: 		.append("[ ").append(upper.toString()).append(" ]");
2803: 	}
2804: 	else {
2805: 	    // variable association -> if no tag found use []
2806: 	    // else search for tag:
2807: 	    // <MultipliciyType> : array|vector|list|slist|map|stack
2808: 	    String multType = item.getTaggedValue("MultiplicityType");
2809: 	    if (multType == null) {
2810: 		// no known container type found
2811: 		sb.append(type).append(' ');
2812: 		sb.append(modifier).append(name).append("[]");
2813: 	    }
2814: 	    else if (multType.equals("vector")) {
2815: 		if (extraIncludes.indexOf("#include <vector>") == -1)
2816: 		    extraIncludes += "#include <vector>\n";
2817: 		containerType = "vector";
2818: 	    }
2819: 	    else if (multType.equals("list")) {
2820: 		if (extraIncludes.indexOf("#include <list>") == -1)
2821: 		    extraIncludes += "#include <list>\n";
2822: 		containerType = "list";
2823: 	    }
2824: 	    else if (multType.equals("slist")) {
2825: 		if (extraIncludes.indexOf("#include <slist>") == -1)
2826: 		    extraIncludes += "#include <slist>\n";
2827: 		containerType = "slist";
2828: 	    }
2829: 	    else if (multType.equals("map")) {
2830: 		if (extraIncludes.indexOf("#include <map>") == -1)
2831: 		    extraIncludes += "#include <map>\n";
2832: 		containerType = "map";
2833: 	    }
2834: 	    else if (multType.equals("stack")) {
2835: 		if (extraIncludes.indexOf("#include <stack>") == -1)
2836: 		    extraIncludes += "#include <stack>\n";
2837: 		containerType = "stack";
2838: 	    }
2839: 
2840: 	    if (containerType != null) {
2841: 		// known container type
2842: 		String includeLine = "#include <" + containerType + ">";
2843: 		if (extraIncludes.indexOf(includeLine) == -1)
2844: 		    extraIncludes += includeLine + "\n";
2845: 		sb.append(containerType).append("< ");
2846: 		sb.append(type).append(modifier);
2847: 		sb.append(" > ").append(name);
2848: 	    }
2849: 	}
2850: 	return sb.toString();
2851:     }
