2857:     public String generateMultiplicityRange(MMultiplicityRange mr) {
2858: 	Integer lower = new Integer(mr.getLower());
2859: 	Integer upper = new Integer(mr.getUpper());
2860: 	if (lower == null && upper == null) return ANY_RANGE;
2861: 	if (lower == null) return "*.." + upper.toString();
2862: 	if (upper == null) return lower.toString() + "..*";
2863: 	if (lower.intValue() == upper.intValue()) return lower.toString();
2864: 	return lower.toString() + ".." + upper.toString();
