1167:      * part of UML - as far as author knows - but important for C++
1168:      * developers)
1169:      * @param elem element to check
1170:      * @param tag_type tag type to check
1171:      */
1172:     private boolean checkAttributeParameter4Tag(MModelElement elem,
1173: 						int tagType) {
1174: 	// first check whether the parameter shall be a pointer of reference
1175:   	Collection tValues = elem.getTaggedValues();
1176:   	if (!tValues.isEmpty()) {
1177: 	    Iterator iter = tValues.iterator();
1178: 	    while (iter.hasNext()) {
1179: 		MTaggedValue tv = (MTaggedValue) iter.next();
1180: 		String tag = tv.getTag();
1181: 		if ((tag.indexOf("ref") != -1 || tag.equals("&"))
1182: 		    && (tagType != SearchPointerTag)) {
1183: 		    return true;
1184: 		} else if ((tag.indexOf("pointer") != -1 || tag.equals("*"))
1185: 			   && (tagType != SearchReferenceTag)) {
1186: 		    return true;
1187: 		}
1188: 	    }
1189: 	}
1190: 	return false;
1191:     }
