1692:     /** 2002-12-13 Achim Spangler
1693:      * generate a single get function for a given attribute and StringBuffer
1694:      */
1695:     private void generateSingleAttributeGet(MAttribute attr, StringBuffer sb) {
1696: 	if (attr.getType() == null) return;
1697: 	// generate for attributes with class-type:
1698: 	// "const <type>& get_<name>( void ) { return <name>; };"
1699: 	// generate for other (small) data types
1700: 	// "<type> get_<name>( void ) { return <name>; };"
1701: 	// generate: "INDENT"
1702: 	sb.append('\n').append(INDENT);
1703: 	sb.append("/** simple access function to get the attribute ");
1704: 	sb.append(attr.getName());
1705: 	sb.append(" by function */\n").append(INDENT);
1706: 	String modifier = generateAttributeParameterModifier(attr);
1707: 	if (modifier != null && modifier.length() > 0)
1708: 	{
1709: 	    // generate: "const <type><modifier>"
1710: 	    sb.append("const ").append(generateClassifierRef(attr.getType()));
1711: 	    sb.append(modifier);
1712: 	}
1713: 	else if (attr.getType() instanceof MClass) {
1714: 	    // generate: "const <type>&"
1715: 	    sb.append("const ").append(generateClassifierRef(attr.getType()));
1716: 	    sb.append("&");
1717: 	} else {
1718: 	    // generate: "<type>"
1719: 	    sb.append(generateClassifierRef(attr.getType()));
1720: 	}
1721: 	// generate: " get_<name>( void ) const { return <name>; };"
1722: 	sb.append(" get_").append(attr.getName());
1723: 	sb.append("( void ) const { return ").append(attr.getName());
1724: 	sb.append("; };");
1725:     }
