1727:     /**
1728:      * Generates the attributes of the body of a class or interface.
1729:      * @param cls
1730:      * @return StringBuffer
1731:      */
1732:     private void generateClassifierBodyTaggedAccess4Attributes(MClassifier cls,
1733: 							       StringBuffer funcPrivate,
1734: 							       StringBuffer funcProtected,
1735: 							       StringBuffer funcPublic)
1736:     {
1737: 	Collection strs = UmlHelper.getHelper().getCore().getAttributes(cls);
1738: 	if (strs.isEmpty() || (generatorPass != header_pass)) return;
1739: 	String accessTag = null;
1740: 
1741: 	Iterator strEnum = strs.iterator();
1742: 	while (strEnum.hasNext())
1743: 	{
1744: 	    MAttribute attr = (MAttribute) strEnum.next();
1745: 	    accessTag = attr.getTaggedValue("set");
1746: 	    if (accessTag != null && accessTag.length() > 0) {
1747: 		if (accessTag.indexOf("public") != -1) {
1748: 		    generateSingleAttributeSet(attr, funcPublic);
1749: 		}
1750: 		if (accessTag.indexOf("protected") != -1) {
1751: 		    generateSingleAttributeSet(attr, funcProtected);
1752: 		}
1753: 		if (accessTag.indexOf("private") != -1) {
1754: 		    generateSingleAttributeSet(attr, funcPrivate);
1755: 		}
1756: 	    }
1757: 
1758: 	    accessTag = attr.getTaggedValue("get");
1759: 	    if (accessTag != null && accessTag.length() > 0) {
1760: 		if (accessTag.indexOf("public") != -1) {
1761: 		    generateSingleAttributeGet(attr, funcPublic);
1762: 		}
1763: 		if (accessTag.indexOf("protected") != -1) {
1764: 		    generateSingleAttributeGet(attr, funcProtected);
1765: 		}
1766: 		if (accessTag.indexOf("private") != -1) {
1767: 		    generateSingleAttributeGet(attr, funcPrivate);
1768: 		}
1769: 	    }
1770: 	}
1771:     }
