1773:     /**
1774:      * Generates the association ends of the body of a class or interface.
1775:      * @param cls
1776:      * @return StringBuffer
1777:      */
1778:     private void generateClassifierBodyOperations(MClassifier cls,
1779: 						  StringBuffer sb)
1780:     {
1781: 	Collection behs = UmlHelper.getHelper().getCore().getOperations(cls);
1782: 	if (behs.isEmpty()) return;
1783:    	String tv = null; // helper for tagged values
1784: 	//
1785: 	// 2002-06-08
1786: 	// Jaap Branderhorst
1787: 	// Bugfix: behs is never null. Should check for isEmpty instead
1788: 	// old code:
1789: 	// if (behs != null)
1790: 	// new code:
1791: 	//
1792: 	sb.append('\n');
1793: 	if (_verboseDocs)
1794: 	{
1795: 	    sb.append(INDENT).append("// Operations\n");
1796: 	}
1797: 
1798: 	// generate tag controlled access functions for attributes
1799: 	StringBuffer funcPrivate = new StringBuffer(80);
1800: 	StringBuffer funcProtected = new StringBuffer(80);
1801: 	StringBuffer funcPublic = new StringBuffer(80);
1802: 	generateClassifierBodyTaggedAccess4Attributes(cls,
1803: 						      funcPrivate,
1804: 						      funcProtected,
1805: 						      funcPublic);
1806: 
1807: 	// generate attributes in order public, protected, private
1808: 	for (int i = 0; i < ALL_PARTS.length; i++) {
1809: 	    int publicProtectedPrivate = ALL_PARTS[i];
1810: 	    Iterator behEnum = behs.iterator();
1811: 	    boolean isVisibilityLinePrinted = false;
1812: 
1813: 	    if ((publicProtectedPrivate == PRIVATE_PART)
1814: 		&& (funcPrivate.length() > 0)) {
1815: 		sb.append("\n private:").append(funcPrivate.toString());
1816: 		isVisibilityLinePrinted = true;
1817: 	    }
1818: 	    if ((publicProtectedPrivate == PROTECTED_PART)
1819: 		&& (funcProtected.length() > 0)) {
1820: 		sb.append("\n protected:").append(funcProtected.toString());
1821: 		isVisibilityLinePrinted = true;
1822: 	    }
1823: 	    if ((publicProtectedPrivate == PUBLIC_PART)
1824: 		&& (funcPublic.length() > 0)) {
1825: 		sb.append("\n public:").append(funcPublic.toString());
1826: 		isVisibilityLinePrinted = true;
1827: 	    }
1828: 
1829: 	    while (behEnum.hasNext())
1830: 	    {
1831: 		MBehavioralFeature bf = (MBehavioralFeature) behEnum.next();
1832: 		MVisibilityKind vis = bf.getVisibility();
1833: 		if ((((publicProtectedPrivate == PUBLIC_PART)
1834: 		      && (MVisibilityKind.PUBLIC.equals(vis)))
1835: 		     || ((publicProtectedPrivate == PROTECTED_PART)
1836: 			 && (MVisibilityKind.PROTECTED.equals(vis)))
1837: 		     || ((publicProtectedPrivate == PRIVATE_PART)
1838: 			 && (MVisibilityKind.PRIVATE.equals(vis))))
1839: 		    && ((generatorPass == header_pass)
1840: 			|| (checkGenerateOperationBody((MOperation) bf)))) {
1841: 		    if ((!isVisibilityLinePrinted)
1842: 			&& (generatorPass == header_pass)) {
1843: 			isVisibilityLinePrinted = true;
1844: 			if (publicProtectedPrivate == PUBLIC_PART) {
1845: 			    sb.append("\n public:");
1846: 			} else if (publicProtectedPrivate == PROTECTED_PART) {
1847: 			    sb.append("\n protected:");
1848: 			} else if (publicProtectedPrivate == PRIVATE_PART) {
1849: 			    sb.append("\n private:");
1850: 			}
1851: 		    }
1852: 
1853: 		    sb.append(generate(bf));
1854: 
1855: 		    tv =
1856: 			generateTaggedValues((MModelElement) bf,
1857: 					     AllButDocTags);
1858: 
1859: 		    if ((cls instanceof MClass)
1860: 			&& (bf instanceof MOperation)
1861: 			&& (!((MOperation) bf).isAbstract())
1862: 			&& (checkGenerateOperationBody((MOperation) bf)))
1863: 		    {
1864: 			// there is no ReturnType in behavioral feature (nsuml)
1865: 			sb.append("\n")
1866: 			    .append(generateMethodBody((MOperation) bf));
1867: 		    }
1868: 		    else
1869: 		    {
1870: 			sb.append(";\n");
1871: 			if (tv.length() > 0)
1872: 			{
1873: 			    sb.append(INDENT).append(tv).append('\n');
1874: 			}
1875: 		    }
1876: 		}
1877: 	    }
1878: 	}
1879:     }
