2087:     public String generateDefaultReturnStatement(MClassifier cls) {
2088: 	if (cls == null) return "";
2089: 
2090: 	String clsName = cls.getName();
2091: 	if (clsName.equals("void")) return "";
2092: 	if (clsName.equals("char")) return INDENT + "return 'x';\n";
2093: 	if (clsName.equals("int")) return INDENT + "return 0;\n";
2094: 	if (clsName.equals("boolean")) return INDENT + "return false;\n";
2095: 	if (clsName.equals("byte")) return INDENT + "return 0;\n";
2096: 	if (clsName.equals("long")) return INDENT + "return 0;\n";
2097: 	if (clsName.equals("float")) return INDENT + "return 0.0;\n";
2098: 	if (clsName.equals("double")) return INDENT + "return 0.0;\n";
2099: 	return INDENT + "return null;\n";
2100:     }
