2102:     public String generateTaggedValues(Object handle, int tagSelection) {
2103: 	MModelElement e = (MModelElement)handle;
2104: 	// cat.info("generateTaggedValues for element: " + e.getName()
2105: 	// + " und selection " + tagSelection);
2106: 
2107: 	Collection tvs = e.getTaggedValues();
2108: 	if (tvs == null || tvs.size() == 0) return "";
2109: 	boolean first = true;
2110: 	StringBuffer buf = new StringBuffer();
2111: 
2112: 	Iterator iter = tvs.iterator();
2113: 	String s = null;
2114: 	while (iter.hasNext())
2115: 	{
2116: 	    s = generateTaggedValue((MTaggedValue) iter.next(), tagSelection);
2117: 	    if (s != null && s.length() > 0)
2118: 	    {
2119: 		if (first) {
2120: 		    /*
2121: 		     * Corrected 2001-09-26 STEFFEN ZSCHALER
2122: 		     *
2123: 		     * Was:
2124: 		     buf.append("// {");
2125: 		     *
2126: 		     * which caused problems with new lines characters
2127: 		     * in tagged values (e.g. comments...). The new
2128: 		     * version still has some problems with tagged
2129: 		     * values containing "*"+"/" as this closes the
2130: 		     * comment prematurely, but comments should be
2131: 		     * taken out of the tagged values list anyway...
2132: 		     */
2133: 
2134: 		    if (tagSelection == DocCommentTags) {
2135: 			// insert main documentation for DocComment at first
2136: 			String doc =
2137: 			    (DocumentationManager.hasDocs(e))
2138: 			    ? DocumentationManager.getDocs(e, INDENT)
2139: 			    : null;
2140: 			if (doc != null && doc.trim().length() > 0) {
2141: 			    buf.append(doc.substring(0, doc.indexOf("*/") + 1));
2142: 			    buf.append("  ");
2143: 			}
2144: 			else
2145: 			{
2146: 			    buf.append("/** ");
2147: 			}
2148: 		    }
2149: 		    else {
2150: 			buf.append("/* {");
2151: 		    }
2152: 		    first = false;
2153: 		} // end first
2154: 		else
2155: 		{
2156: 		    if (tagSelection == DocCommentTags)
2157: 		    {
2158: 			buf.append("\n").append(INDENT).append(" *  ");
2159: 		    }
2160: 		    else
2161: 		    {
2162: 			buf.append(", ");
2163: 		    }
2164: 		} // end not first tag
2165: 		buf.append(s);
2166: 	    } // end tag not empty
2167: 	} // end while
2168: 	/*
2169: 	 * Corrected 2001-09-26 STEFFEN ZSCHALER
2170: 	 *
2171: 	 * Was:
2172: 	 if (!first) buf.append("}\n");
2173: 	 *
2174: 	 * which caused problems with new-lines in tagged values.
2175: 	 */
2176: 	if (!first)
2177: 	{
2178: 	    if (tagSelection == DocCommentTags)
2179: 	    {
2180: 		buf.append("\n").append(INDENT).append(" */\n");
2181: 	    }
2182: 	    else
2183: 	    {
2184: 		buf.append ("}*/\n");
