2765:     public String generateMultiplicity(MModelElement item, String name,
2766: 				       MMultiplicity m, String modifier) {
2767: 	String type = null;
2768: 	String containerType = null;
2769: 	// cat.info("generateMultiplicity mit item" + item.getName() +
2770: 	// ", name: " + name + ", modifier: " + modifier);
2771: 
2772: 	MClassifier typeCls = null;
2773: 	if (item instanceof MAssociationEnd) {
2774: 	    typeCls = ((MAssociationEnd) item).getType();
2775: 	} else if (item instanceof MAttribute) {
2776: 	    typeCls = ((MAttribute) item).getType();
2777: 	} else if (item instanceof MClassifier) {
2778: 	    type = ((MClassifier) item).getName();
2779: 	} else {
2780: 	    type = "";
2781: 	}
2782: 	if (typeCls != null) type = generateNameWithPkgSelection(typeCls);
2783: 	// cat.info("resolved type_name: " + type);
2784: 	if (m == null) { return (type + " " + modifier + name); }
2785: 	StringBuffer sb = new StringBuffer(80);
2786: 	int countUpper = m.getUpper(),
2787: 	    countLower = m.getLower();
2788: 	// cat.info("resolved int upper/lower bounds");
2789: 	Integer lower = new Integer(countLower);
2790: 	Integer upper = new Integer(countUpper);
2791: 	// cat.info("resolved Integer upper/lower bounds");
2792: 
2793: 	if (countUpper	== 1) {
2794: 	    // simple generate identifier for default 0:1, 1:1 association
2795: 	    sb.append(type).append(' ').append(modifier).append(name);
2796: 	}
2797: 	else if (countUpper == countLower) {
2798: 	    // fixed array -> <type> <name>[<count>];
2799: 	    sb.append(type).append(' ').append(modifier).append(name)
2800: 		.append("[ ").append(upper.toString()).append(" ]");
2801: 	}
2802: 	else {
2803: 	    // variable association -> if no tag found use []
2804: 	    // else search for tag:
2805: 	    // <MultipliciyType> : array|vector|list|slist|map|stack
2806: 	    String multType = item.getTaggedValue("MultiplicityType");
2807: 	    if (multType == null) {
2808: 		// no known container type found
2809: 		sb.append(type).append(' ');
2810: 		sb.append(modifier).append(name).append("[]");
2811: 	    }
2812: 	    else if (multType.equals("vector")) {
2813: 		if (extraIncludes.indexOf("#include <vector>") == -1)
2814: 		    extraIncludes += "#include <vector>\n";
2815: 		containerType = "vector";
2816: 	    }
2817: 	    else if (multType.equals("list")) {
2818: 		if (extraIncludes.indexOf("#include <list>") == -1)
2819: 		    extraIncludes += "#include <list>\n";
2820: 		containerType = "list";
2821: 	    }
2822: 	    else if (multType.equals("slist")) {
2823: 		if (extraIncludes.indexOf("#include <slist>") == -1)
2824: 		    extraIncludes += "#include <slist>\n";
2825: 		containerType = "slist";
2826: 	    }
2827: 	    else if (multType.equals("map")) {
2828: 		if (extraIncludes.indexOf("#include <map>") == -1)
2829: 		    extraIncludes += "#include <map>\n";
2830: 		containerType = "map";
2831: 	    }
2832: 	    else if (multType.equals("stack")) {
2833: 		if (extraIncludes.indexOf("#include <stack>") == -1)
2834: 		    extraIncludes += "#include <stack>\n";
2835: 		containerType = "stack";
2836: 	    }
2837: 
2838: 	    if (containerType != null) {
2839: 		// known container type
2840: 		String includeLine = "#include <" + containerType + ">";
2841: 		if (extraIncludes.indexOf(includeLine) == -1)
2842: 		    extraIncludes += includeLine + "\n";
2843: 		sb.append(containerType).append("< ");
2844: 		sb.append(type).append(modifier);
2845: 		sb.append(" > ").append(name);
2846: 	    }
2847: 	}
2848: 	return sb.toString();
2849:     }
