275: 	if (src == resultsTable) {
276: 	    int row = resultsTable.getSelectionModel().getMinSelectionIndex();
277: 	    if (row < 0)
278: 		return;
279: 	    sel = results.elementAt(row);
280: 	    d = (Diagram) diagrams.elementAt(row);
281: 	} else if (src == relatedTable) {
282: 	    int row = relatedTable.getSelectionModel().getMinSelectionIndex();
283: 	    if (row < 0)
284: 		return;
285: 	    numJumpToRelated++;
