580:     /**
581:      * Searches for a type/classifier with name s. If the type is not found,
582:      * a new type is created and added to the current namespace.
583:      * @param s the name of the type/classifier to be found
584:      * @return MClassifier
585:      */
586:     public Object findType(String s) {
587:         return findType(s, true);
588:     }
