62: /**
63:  * Fig to show an object on a sequence diagram. The fig consists of an
64:  * upper box that shows the name of the object (the owner) and a
65:  * lifeline. The lifeline consists of lifeline elements. An element
66:  * can be a dashed line (no link attached) or a rectangle (link
67:  * attached).
68:  * @author jaap.branderhorst@xs4all.nl
69:  * Aug 11, 2003
70:  */
71: public class FigClassifierRole extends FigNodeModelElement
72:     implements MouseListener, HandlerFactory {
73: 
74:     /**
75:      * Logger.
76:      */
77:     private static final Logger LOG =
78:         Logger.getLogger(FigClassifierRole.class);
79: 
80:     /**
81:      * The width of an activation box.
82:      */
83:     public static final int WIDTH = 20;
84: 
85:     /**
86:      * The margin between the outer box and the name and stereotype text box.
87:      */
88:     public static final int MARGIN = 10;
89: 
90:     /**
91:      * The distance between two rows in the object rectangle.
92:      */
93:     public static final int ROWDISTANCE = 2;
94: 
95:     /**
96:      * The defaultheight of the object rectangle. That's 3 times the rowheight +
97:      * 3 times a distance of 2 between the rows + the stereoheight.
98:      */
99:     public static final int DEFAULT_HEIGHT =
100:         (3 * ROWHEIGHT + 3 * ROWDISTANCE + STEREOHEIGHT);
101: 
102:     /**
103:      * The defaultwidth of the object rectangle.
104:      */
105:     public static final int MIN_HEAD_WIDTH = 3 * DEFAULT_HEIGHT / 2;
106: 
107:     /**
108:      * The filled box for the object box (object fig without lifeline).
109:      */
110:     private FigRect headFig;
111: 
112:     /**
113:      * The lifeline (dashed line under the object box to which activations are
114:      * attached).
115:      */
116:     private FigLine lifeLine;
117: 
118:     /**
119:      * The list where the nodes to which links can be attached are stored.
120:      */
121:     private List linkPositions = new ArrayList();
122: 
123:     /**
124:      * The comma seperated list of base names of the classifierRole(s)
125:      * that this object represents.
126:      */
127:     private String baseNames = "";
128: 
129:     /**
130:      * The name of the classifier role (the owner of this fig).
131:      */
132:     private String classifierRoleName = "";
133: 
134:     /**
135:      * The set of activation figs.
136:      */
137:     private Set activationFigs;
138: 
139:     /**
140:      * Default constructor. Constructs the object rectangle, the lifeline,
141:      * the name box and the stereotype box.
142:      */
143:     public FigClassifierRole() {
144:         super();
145:         headFig =
146:             new FigRect(
