205:     public void layoutContainer(Container parent) {
206:         synchronized (parent.getTreeLock()) {
207:             int sectionX = parent.getInsets().left;
208: 
209:             ArrayList components = new ArrayList();
210:             int sectionCount = getSectionCount(parent);
211:             int sectionWidth = getSectionWidth(parent, sectionCount);
212:             for (int i = 0; i < parent.getComponentCount(); ++i) {
213:                 if (parent.getComponent(i) instanceof Seperator) {
214:                     layoutSection(parent, sectionX, sectionWidth, components);
215:                     sectionX += sectionWidth + _hgap;
216:                     components.clear();
217:                 } else {
218:                     components.add(parent.getComponent(i));
219:                 }
220:             }
221:             layoutSection(parent, sectionX, sectionWidth, components);
222:         }
223:     }
224: 
225:     /** Determine the number of sections.
226:      * There is only ever one section if oriented vertically.
227:      * If oriented horizontally the number of sections is deduced from the number of Splitters
228:      * in the parent container.
229:      */
230:     private int getSectionCount(Container parent) {
231:         int sectionCount = 1;
232:         int componentCount = parent.getComponentCount();
233:         if (ignoreSplitters.equals(Horizontal.getInstance())) {
234:             for (int i = 0; i < componentCount; ++i) {
235:                 if (parent.getComponent(i) instanceof Seperator)
236:                     ++sectionCount;
237:             }
238:         }
239:         return sectionCount;
240:     }
241:     
242:     /**
243:      * Determine the width of each section from the section count.
244:      * This is the working width minus the gaps between sections. This result is then divided
245:      * equally by the section count.
246:      */
247:     private int getSectionWidth(Container parent, int sectionCount) {
248:         return (getUsableWidth(parent)-(sectionCount-1)*_hgap) / sectionCount;
249:     }
250: 
251:     /**
252:      * Determine the usable width of the parent.
253:      * This is the full width minus any borders.
254:      */
255:     private int getUsableWidth(Container parent) {
256:         Insets insets = parent.getInsets();
257:         return parent.getWidth() - (insets.left + insets.right);
258:     }
259:     
260:     /**
261:      * Layout a single section
262:      */
263:     private void layoutSection(Container parent, int sectionX, int sectionWidth, ArrayList components) {
264:         ArrayList rowHeights = new ArrayList();
265: 
266:         int componentCount = components.size();
267:         if (componentCount == 0) {
268:             return;
269:         }
270: 
271:         int childWidth, childHeight;
272:         int labelWidth = 0;
273:         int unknownHeightCount = 0;
274:         int totalHeight = 0;
275: 
276:         // Build up an array list of the heights of each label/component pair.
277:         // Heights of zero indicate a proportional height.
278:         for (int i = 0; i < componentCount; ++i) {
279:             Component childComp = (Component) components.get(i);
280:             if (childComp instanceof JLabel) {
281:                 JLabel jlabel = (JLabel) childComp;
282:                 childWidth = (int) childComp.getPreferredSize().getWidth();
283:                 if (childWidth > labelWidth) {
284:                     labelWidth = childWidth;
285:                 }
286:                 childHeight = (int) childComp.getPreferredSize().getHeight();
287: 
288:                 childComp = jlabel.getLabelFor();
289:                 if (childComp != null)
290:                     i++;
291:                 if (childComp != null && childComp.getMinimumSize() != null && childHeight < childComp.getMinimumSize().getHeight()) {
292:                     if (childComp != null && childComp.getPreferredSize() != null && childComp.getMinimumSize().getHeight() < childComp.getPreferredSize().getHeight()) {
293:                         // If the preferred size is greater then the minimum size then this child components
294:                         // actual current size is currently unknown. It will be calculated later is a
295:                         // propertion of the available left over space.
296:                         // For now this is flagged as zero.
297:                         childHeight = 0;
298:                         ++unknownHeightCount;
299:                     } else {
300:                         // If a preferred height is not given or is the same as the minimum height then
301:                         // fix the height of this row.
302:                         childHeight = (int) childComp.getMinimumSize().getHeight();
303:                     }
304:                 }
305:             } else {
306:                 // to manage the case there are no label/component pairs but just one component
307:                 childHeight = (int) childComp.getPreferredSize().getHeight();
308:                 if (childComp != null && childComp.getPreferredSize() != null && childComp.getMinimumSize().getHeight() < childComp.getPreferredSize().getHeight()) {
309:                     // If the preferred size is greater then the minimum size then this child components
310:                     // actual current size is currently unknown. It will be calculated later is a
311:                     // propertion of the available left over space.
312:                     // For now this is flagged as zero.
313:                     childHeight = 0;
314:                     ++unknownHeightCount;
315:                 } else {
316:                     // If a preferred height is not given or is the same as the minimum height then
317:                     // fix the height of this row.
318:                     childHeight = (int) childComp.getMinimumSize().getHeight();
319:                 }
320:             }
321:             totalHeight += childHeight + _vgap;
322:             rowHeights.add(new Integer(childHeight));
323:         }
324:         totalHeight -= _vgap;
325:         
326:         Insets insets = parent.getInsets();
327:         int parentHeight = parent.getHeight() - (insets.top + insets.bottom);
328:         // Set the child components to the heights in the array list calculating the
329:         // height of any proportional component on the fly.
330:         // FIXME - This assumes that the JLabel and the component it labels have
331:         // been added to the parent component consecutively.
332:         int y = insets.top;
333:         int row = 0;
334:         for (int i = 0; i < componentCount; ++i) {
335:             Component childComp = (Component) components.get(i);
336:             if (childComp.isVisible()) {
337:                 int rowHeight;
338:                 int componentWidth = sectionWidth;
339:                 int componentX = sectionX;
340:                 // If the component is a JLabel which has another component assigned
341:                 // then position/size the label and calculate the size of the registered
342:                 // component
343:                 if (childComp instanceof JLabel && ((JLabel)childComp).getLabelFor() != null) {
344:                     i++; // Assumes the next child is the labelled component (could be improved)
345:                     JLabel jlabel = (JLabel) childComp;
346:                     childComp = jlabel.getLabelFor();
347:                     jlabel.setBounds(sectionX, y, labelWidth, (int) jlabel.getPreferredSize().getHeight());
348:                     componentWidth = sectionWidth - (labelWidth + _hgap);
349:                     componentX = sectionX + labelWidth + _hgap;
350:                 }
351:                 rowHeight = ((Integer) rowHeights.get(row)).intValue();
352:                 if (rowHeight == 0) {
353:                     rowHeight = calculateHeight(parentHeight, totalHeight, unknownHeightCount--, childComp);
354:                     totalHeight += rowHeight;
355:                 }
356:                 // Make sure the component width isn't any greater than its maximum allowed width
357:                 if (childComp.getMaximumSize() != null && childComp.getMaximumSize().getWidth() < componentWidth) {
358:                      componentWidth = (int)childComp.getMaximumSize().getWidth();
359:                 }
360:                 childComp.setBounds(componentX, y, componentWidth, rowHeight);
361:                 y += rowHeight + _vgap;
362:                 ++row;
363:             }
364:         }
365:     }
366: 
367:     private int calculateHeight(int parentHeight, int totalHeight, int unknownHeightsLeft, Component childComp) {
368:         int rowHeight = (parentHeight - totalHeight) / unknownHeightsLeft;
369:         if (rowHeight < childComp.getMinimumSize().getHeight()) {
370:             rowHeight = (int) childComp.getMinimumSize().getHeight();
371:         }
372:         return rowHeight;
373:     }
