379:     public int getHgap() {
380:         return _hgap;
381:     }
382: 
383:     public void setHgap(int hgap) {
384:         _hgap = hgap;
385:     }
386: 
387:     public int getVgap() {
388:         return _vgap;
389:     }
390: 
391:     public void setVgap(int vgap) {
392:         _vgap = vgap;
393:     }
394: }
