53: /**
54:  * This class implements an event pump for all modelevents (MEvents
55:  * with the current NSUML model). Two kinds of listeners can be
56:  * registred to the pump: listeners to class events and listeners to
57:  * object events. The pump dispatches all events fired by objects of a
58:  * certain class to the class listeners (listeners that are registred
59:  * via addClassModelEventListener). Furthermore, it dispatches all
60:  * events to listeners that are registered for a certain object if
61:  * this object fired the original event.<p>
62:  *
63:  * Maybe this class should dispatch a thread to handle the incoming
64:  * event in the future.
65:  * @since Oct 14, 2002
66:  * @author jaap.branderhorst@xs4all.nl
67:  * @deprecated by Linus Tolke as of 0.17.1. This class is part of the 
68:  *             NSUML-dependant API of the model component. Use the NSUML-free 
69:  *             {@link org.argouml.model.Model#getPump()} and the
70:  *             {@link org.argouml.model.ModelEventPump} interface.
71:  */
72: public final class UmlModelEventPump implements MElementListener {
73: 
74:     /** The Logger. */
75:     private static final Logger LOG = 
76: 	    Logger.getLogger(UmlModelEventPump.class);
77: 
78:     /**
79:      * Indicate wether we pump events to listeners yes or no. 
80:      * There is some fault in the NSUML implementation
81:      * but where...
82:      */
83:     private boolean pumping = true;
84: 
85:     /**
86:      * "remove".
87:      */
88:     public static final String REMOVE = "remove";
89: 
90:     private static UmlModelEventPump theInstance = new UmlModelEventPump();
91: 
92:     /**
93:      * The 'map' with the eventlistenerlists per modelelement.
94:      */
95:     private EventListenerHashMap listenerMap = new EventListenerHashMap();
96: 
97:     private ClassListenerHashMap classListenerMap = new ClassListenerHashMap();
98: 
99:     private EventTreeDefinition definition = new EventTreeDefinition();
100: 
101:     /**
102:      * Singleton access method.
103:      *
104:      * @return UmlModelEventPump
105:      */
106:     public static synchronized UmlModelEventPump getPump() {
107:         return theInstance;
108:     }
109: 
110:     /**
111:      * Constructor for UmlModelEventPump, initialises the NSUML event policy.
112:      */
113:     private UmlModelEventPump() {
114:         super();
115:         // Initialize NSUML
116: 	MFactoryImpl.setEventPolicy(MFactoryImpl.EVENT_POLICY_IMMEDIATE);
117:     }
118: 
119:     /**
120:      * Adds a listener that listens to all modelevents that are named
121:      * eventNames and that occur to instances of a given
122:      * modelClass.<p>
123:      *
124:      * If you want the listener to be registered for remove events
125:      * (that is: an instance of the class the listener is listening
126:      * too is removed), then you have to register for the eventname
127:      * "remove".<p>
128:      *
129:      * @param listener is the listener to add.
130:      * @param metaType is the given model class
131:      * @param eventNames is a array of strings with event names.
132:      * @throws IllegalArgumentException if one of the arguments is null or if
133:      * the modelClass is not a subclass of MBase.
134:      * @throws IllegalStateException if the listener is allready registred
135:      */
136:     public void addClassModelEventListener(MElementListener listener,
137: 					   Object metaType,
138: 					   String[] eventNames) {
139:         Class modelClass = (Class) metaType;
140: //      We don't support non-NSUML modeleventlisteners yet, 
141: //      so we return without addition.
142:         if (!MBase.class.isAssignableFrom(modelClass)) {
143:             return;
144:         }
145:         if (listener == null
146:             || modelClass == null
147:             || eventNames == null           
148:             || eventNames.length == 0) {
149:             throw new IllegalArgumentException("Tried to add illegal class"
150: 					       + " modeleventlistener to "
151: 					       + "possible null class");
152:         }
153:         for (int i = 0; i < eventNames.length; i++) {
154:             executeAddClassModelEventListener(
155: 					      listener,
156: 					      modelClass,
157: 					      eventNames[i]);
158:         }
159:     }
160: 
161:     /**
162:      * Convinience method to add a listener that only listens to one specific 
163:      * event.
164:      *
165:      * @param listener The listener to add
166:      * @param metaType The listener should listen to instances of this class
167:      * @param eventName The name of the event the listener wants to listen 
168:      * too.
169:      */
170:     public void addClassModelEventListener(MElementListener listener,
171: 					   Object metaType,
172: 					   String eventName) {
173:         Class modelClass = (Class) metaType;
174:         // We don't support non-NSUML modeleventlisteners yet, 
175:         // so we return without addition.
176:         
177:         if (!MBase.class.isAssignableFrom(modelClass)) {
178:             return;
179:         }
180:         if (listener == null
181:             || modelClass == null
182:             || eventName == null
183:             || eventName.equals("")) {
184:             throw new IllegalArgumentException();
185:         }
186:         executeAddClassModelEventListener(listener, modelClass, eventName);
187:     }
188: 
189:     /**
190:      * Does the actual adding.
191:      *
192:      * @param listener The listener to add
193:      * @param modelClass The listener should listen to instances of this class
194:      * @param eventName The name of the event the listener wants to listen 
195:      */
196:     private synchronized void executeAddClassModelEventListener(
197: 	    MElementListener listener,
198: 	    Class modelClass,
199: 	    String eventName) {
200:         // first register the listener for all elements allready in
201:         // the model modelClass = formatClass(modelClass);
202:         Collection col =
203:             ModelManagementHelper.getHelper()
204: 	        .getAllModelElementsOfKind(modelClass);
205:         
206:         if (col == Collections.EMPTY_LIST) {
207:             col = new ArrayList();
208:         }
209:         
210:         /*
211:         if (modelClass.isAssignableFrom(MModel.class)) {
212:             Object root =
213:                 ProjectManager.getManager().getCurrentProject().getRoot();
214:             if (root != null)
215:                 col.add(root);
216:         }
217:         */
218:         modelClass = formatClass(modelClass);
219:         EventKey[] keys = definition.getEventTypes(modelClass, eventName);
220:         Iterator it = col.iterator();
221:         while (it.hasNext()) {
222:             MBase base = (MBase) it.next();
223:             for (int i = 0; i < keys.length; i++) {
224:                 listenerMap.put(base, keys[i], listener);
225:             }
226:         }
227:         // add the class to the 'interested classes list' so the listener is 
228:         // added on creation of a modelelement
229:         for (int i = 0; i < keys.length; i++) {
230:             classListenerMap.put(modelClass, keys[i], listener);
231:         }
232:     }
233:     /**
234:      * Retrieves the  implementation class belonging to some given class. For 
235:      * example, retrieves ClassImpl.class if the input was Class.class or 
236:      * ClassImpl.class.
237:      * @param inputClass An interface or implementation class from NSUML
238:      * @return The implementation class from NSUML
239:      */
240:     private Class formatClass(Class inputClass) {
241:         String name = inputClass.getName();
242:         if (name.endsWith("Impl")) {
243:             return inputClass;
244:         } else {
245:             try {
246:                 Class returnClass = Class.forName(name + "Impl");
247:                 return returnClass;
248:             } catch (ClassNotFoundException ignorable) {
249:                 // cannot happen
250:             }
251:         }
252:         return null;
253: 
254:     }
255: 
256:     /**
257:      * Removes a listener that listens to all modelevents fired by instances of
258:      * modelClass and that have the original name eventNames.
259:      * @param listener The listener to remove
260:      * @param modelClass The class the listener does not want to listen to 
261:      * instances anymore
262:      * @param eventNames The eventnames the listener does not want to listen to
263:      * anymore
264:      */
265:     public void removeClassModelEventListener(
266: 					      MElementListener listener,
267: 					      Class modelClass,
268: 	
269: 					      String[] eventNames) {
270:         // we don't support eventlisteners other then NSUML ModelEventListener.
271:         // to be forward compatible with other ModelEventListeners, 
272:         // we do not throw an exception but
273:         // simply return.
274:         if (!MBase.class.isAssignableFrom(modelClass)) {
275:             // throw new IllegalArgumentException();
276:             return;
277:         }
278:         if (listener == null
279:             || modelClass == null
280:             || eventNames == null
281:             || eventNames.length == 0) {
282:             throw new IllegalArgumentException(
283:                     "Tried to remove invalid listener");
284:         }
285:         for (int i = 0; i < eventNames.length; i++) {
286:             executeRemoveClassModelEventListener(
287: 						 listener,
288: 						 modelClass,
289: 						 eventNames[i]);
290:         }
291:     }
292: 
293:     /**
294:      * Convinience method to remove a listener that listens to events named 
295:      * eventName that are fired by instances of modelClass.
296:      * @param listener The listener to remove
297:      * @param modelClass The class the listener does not want to listen to 
298:      * instances anymore
299:      * @param eventName The eventname the listener does not want to listen to
300:      * anymore
301:      */
302:     public void removeClassModelEventListener(
