1374:     public EventListenerList[] getListenerList(Class element) {
1375:         // element = formatClass(element);
1376:         Class[] hierarchy = getHierarchy(element);
1377:         EventListenerList[] lists = new EventListenerList[hierarchy.length];
1378:         EventListenerList list = null;
1379:         for (int i = 0; i < lists.length; i++) {
1380:             list = (EventListenerList) listenerMap.get(hierarchy[i].getName());
1381:             if (list == null) {
1382:                 lists[i] = new EventListenerList();
1383:             } else {
1384:                 lists[i] = list;
1385:             }
1386:         }
1387:         return lists;
1388:     }
1389: 
1390:     private Class[] getHierarchy(Class clazz) {
1391:         Class[] returnClass = null;
1392:         if (clazz != Object.class) {
1393:             Class[] tmp = getHierarchy(clazz.getSuperclass());
1394:             returnClass =
1395:                 (Class[]) Array.newInstance(Class.class, tmp.length + 1);
1396:             System.arraycopy(tmp, 0, returnClass, 0, tmp.length);
1397:             returnClass[tmp.length] = clazz;
1398:         } else {
1399:             returnClass = new Class[] {
1400: 		clazz,
1401: 	    };
1402:         }
1403:         return returnClass;
1404:     }
1405: 
