180:      */
181:     public void initialize(Object owner) {
182:         super.initialize(owner);
183:         if (org.argouml.model.ModelFacade.isANamespace(owner))
184:             setNamespace(owner);
185:         else
186:             LOG.debug("unknown object in UMLDiagram initialize:" + owner);
187:     }
