199:     /**
200:      * sets the namespace of the Diagram, and
201:      * adds the diagram as a listener of its namspace in the UML model.
202:      * (so that it can delete itself when the model element is deleted).
203:      *
204:      * @param ns the namespace
205:      */
206:     public void setNamespace(Object ns) {
207:         if (!ModelFacade.isANamespace(ns)) {
208:             LOG.error("Not a namespace");
209:             LOG.error(ns);
210:             throw new IllegalArgumentException("Given object not a namespace");
211:         }
212:         namespace = ns;
213:         // add the diagram as a listener to the namspace so
214:         // that when the namespace is remove()d the diagram is deleted also.
215:         UmlModelEventPump.getPump().addModelEventListener(
216:             this,
217:             namespace,
218:             UmlModelEventPump.REMOVE);
219:     }
