327:     private Object[] getShapePopupActions() {
328:         Object actions[][] = {
329: 	    {
330: 		_actionRectangle, _actionRRectangle
331: 	    },
332: 	    {
333:                 _actionCircle, _actionLine }, {
334:                 _actionText, _actionPoly }, {
335:                 _actionSpline, _actionInk }
336:         };
337: 
338:         return actions;
339:     }
