397:     /**
398:      * not used the UMLDiagram is only interested in the removed() event.
399:      *
400:      * @see ru.novosoft.uml.MElementListener#recovered(ru.novosoft.uml.MElementEvent)
401:      */
402:     public void recovered(MElementEvent e) {
403:     }
404: 
405:     /**
406:      * Removes the UMLDiagram and all the figs on it as listener to 
407:      * UmlModelEventPump. Is called by setTarget in TabDiagram to improve 
408:      * performance. 
409:      *
410:      */
411:     public void removeAsTarget() {
412:         Enumeration elems = elements();
413:         UmlModelEventPump pump = UmlModelEventPump.getPump();
414:         while (elems.hasMoreElements()) {
415:             Object o = elems.nextElement();
416:             if (ModelFacade.isAElementListener(o)) {
417:                 MElementListener listener = (MElementListener) o;
418:                 Fig fig = (Fig) o;
419:                 pump.removeModelEventListener(listener, fig.getOwner());
420:             }
421:         }
422:         pump.removeModelEventListener(this, getNamespace());
423: 
424:     }
425: 
426:     /**
427:      * Adds the UMLDiagram and all the figs on it as listener to
428:      * UmlModelEventPump.  Together with removeAsModelListener this is
429:      * a performance improvement.
430:      *
431:      */
432:     public void setAsTarget() {
433:         Enumeration elems = elements();
434:         while (elems.hasMoreElements()) {
435:             Fig fig = (Fig) elems.nextElement();
436:             if (org.argouml.model.ModelFacade.isAElementListener(fig)) {
437:                 Object owner = fig.getOwner();
438:                 // pump.addModelEventListener((MElementListener)fig, owner);
439:                 // this will make sure all the correct event listeners are set. 
440:                 fig.setOwner(null);
441:                 fig.setOwner(owner);
442:             }
443:         }
444:     }
445: 
446:     /**
447:      * Set all toolbar buttons to unselected other then the toolbar button
448:      * with the supplied action.
449:      *
450:      * @param otherThanAction the action of the button 
451:      *                        that is NOT to be deselected
452:      */
453:     public void deselectOtherTools(Action otherThanAction) {
454:         //cat.debug("Looking for action " + otherThanAction);
455:         int toolCount = toolBar.getComponentCount();
456:         for (int i = 0; i < toolCount; ++i) {
457:             Component c = toolBar.getComponent(i);
458:             if (c instanceof ToolButton) {
459:                 ToolButton tb = (ToolButton) c;
460:                 Action action = tb.getRealAction();
461:                 if (action instanceof RadioAction) {
462:                     action = ((RadioAction) action).getAction();
463:                 }
464:                 Action otherAction = otherThanAction;
465:                 if (otherThanAction instanceof RadioAction) {
466:                     otherAction = ((RadioAction) otherThanAction).getAction();
467:                 }
468:                 if (!action.equals(otherAction)) {
469:                     //cat.debug("Unselecting " + tb);
470:                     tb.setSelected(false);
471:                     ButtonModel bm = tb.getModel();
472:                     bm.setRollover(false);
473:                     bm.setSelected(false);
474:                     bm.setArmed(false);
475:                     bm.setPressed(false);
476:                     tb.setBorderPainted(false);
477:                 } else {
478:                     //cat.debug("Selecting " + tb);
479:                     tb.setSelected(true);
480:                     ButtonModel bm = tb.getModel();
481:                     bm.setRollover(true);
482:                     tb.setBorderPainted(true);
483:                 }
484:             }
485:         }
486:     }
487: 
488:     /**
489:      * Set all toolbar buttons to unselected other then the toolbar button
490:      * with the supplied action.
491:      */
492:     public void deselectAllTools() {
493:         int toolCount = toolBar.getComponentCount();
494:         for (int i = 0; i < toolCount; ++i) {
495:             Component c = toolBar.getComponent(i);
496:             if (c instanceof ToolButton) {
497:                 ToolButton tb = (ToolButton) c;
498:                 Action action = tb.getRealAction();
499:                 if (action instanceof RadioAction) {
500:                     action = ((RadioAction) action).getAction();
501:                 }
502:                 tb.setSelected(false);
503:                 ButtonModel bm = tb.getModel();
504:                 bm.setRollover(false);
505:                 bm.setSelected(false);
506:                 bm.setArmed(false);
507:                 bm.setPressed(false);
508:                 tb.setBorderPainted(false);
509:             }
510:         }
511:     }
512: } /* end class UMLDiagram */
