163: class ActionOpen extends UMLAction {
164:   public ActionOpen() { super("Open..."); }
165:   public void actionPerformed(ActionEvent e) {
166:     ProjectBrowser pb = ProjectBrowser.TheInstance;
167:     try {
168:       JFileChooser chooser = new JFileChooser();
169:       ArgoFileFilter filter = new ArgoFileFilter();
170:       chooser.addChoosableFileFilter(filter);
171:       chooser.setFileFilter(filter);
172:       int retval = chooser.showOpenDialog(pb);
173:       if(retval == 0) {
174: 	File theFile = chooser.getSelectedFile();
175: 	if(theFile != null) {
176: 	  String pathname = chooser.getSelectedFile().getAbsolutePath();
177:     	pb.showStatus("Reading " + pathname + "...");
178:     	FileInputStream fis = new FileInputStream(pathname);
179:     	ObjectInput s = new ObjectInputStream(fis);
180:     	Project p = (Project) s.readObject();
181: 	p.postLoad();
182: 	if (fis != null) fis.close();
183:     	pb.showStatus("Read " + pathname);
184: 	pb.setProject(p);
185: 	return;
186: 	}
187:       }
188:       JOptionPane.showMessageDialog(pb, "No file chosen");
189:     }
190:     catch (FileNotFoundException ignore) {
191:       System.out.println("got an FileNotFoundException");
192:      }
193:     catch (java.lang.ClassNotFoundException ignore) {
194:       System.out.println("got an ClassNotFoundException");
195:      }
196:     catch (IOException ignore) {
197:       System.out.println("got an IOException");
198:     }
199: 
200:   }
201: } /* end class ActionOpen */
