781: class ActionGenerateOne extends UMLAction {
782:   public ActionGenerateOne() { super("Generate Selected Classes"); }
783: 
784:   public void actionPerformed(ActionEvent e) {
785:     ProjectBrowser pb = ProjectBrowser.TheInstance;
786:     Editor ce = uci.gef.Globals.curEditor();
787:     Vector sels = ce.getSelectionManager().getFigs();
788:     java.util.Enumeration enum = sels.elements();
789:     while (enum.hasMoreElements()) {
790:       Fig f = (Fig) enum.nextElement();
791:       Object owner = f.getOwner();
792:       if (!(owner instanceof MMClass) && !(owner instanceof Interface)) continue;
793:       Classifier cls = (Classifier) owner;
794:       String name = cls.getName().getBody();
795:       if (name == null || name.length() == 0) return;
796:       String path = ".";
797:       pb.showStatus("Generating source file for " + name + "...");
798:       GeneratorJava.GenerateFile(cls, path);
799:       pb.showStatus("Generating source file for " + name + "... done.");
800:       //pb.showStatus(" ");
801:     }
802:   }
803: 
804:   public boolean shouldBeEnabled() {
805:     if (!super.shouldBeEnabled()) return false;
806:     Editor ce = uci.gef.Globals.curEditor();
807:     Vector sels = ce.getSelectionManager().getFigs();
808:     java.util.Enumeration enum = sels.elements();
809:     boolean foundOne = false;
810:     while (enum.hasMoreElements()) {
811:       Fig f = (Fig) enum.nextElement();
812:       Object owner = f.getOwner();
813:       if (!(owner instanceof Classifier)) continue;
814:       Classifier cls = (Classifier) owner;
815:       String name = cls.getName().getBody();
816:       if (name == null || name.length() == 0) return false;
817:       foundOne = true;
818:     }
819:     return foundOne;
820:   }
821: } /* end class ActionGenerateOne */
