1167:     public String generateMultiplicity(Object param) {
1168: 	MMultiplicity m = (MMultiplicity) param;
1169: 	if (m == null) { return ""; }
1170: 	if (MMultiplicity.M0_N.equals(m)) return ANY_RANGE;
1171: 	String s = "";
1172: 	Collection v = m.getRanges();
1173: 	if (v == null) return s;
1174: 	Iterator rangeEnum = v.iterator();
1175: 	while (rangeEnum.hasNext()) {
1176: 	    MMultiplicityRange mr = (MMultiplicityRange) rangeEnum.next();
1177: 	    s += generateMultiplicityRange(mr);
1178: 	    if (rangeEnum.hasNext()) s += ",";
1179: 	}
1180: 	return s;
1181:     }
