776: 	    // Build doccomment
777: 	    sDocComment += " @element-type " + ae.getType().getName();
778: 
779: 	    sDocComment += "\n" +
780: 		INDENT + " */";
781: 
782: 	    return sDocComment;
783: 	}
784: 	else {
785: 	    return ((sDocComment != null) ? (sDocComment) : (""));
