789:     /**
790:      * Enhance/Create the doccomment for the given model element, including tags
791:      * for any OCL constraints connected to the model element. The tags generated
792:      * are suitable for use with the ocl injector which is part of the Dresden OCL
793:      * Toolkit and are in detail:
794:      *
795:      * &nbsp;@invariant for each invariant specified
796:      * &nbsp;@precondition for each precondition specified
797:      * &nbsp;@postcondition for each postcondition specified
798:      *
799:      * @since 2001-09-26 ArgoUML 0.9.3
800:      * @author Steffen Zschaler
801:      *
802:      * @param me the model element for which the documentation comment is needed
803:      * @return the documentation comment for the specified model element, either
804:      * enhanced or completely generated
805:      */
806:     public String generateConstraintEnrichedDocComment (MModelElement me) {
807: 	// Retrieve any existing doccomment
808: 	String sDocComment = DocumentationManager.getDocs (me, GeneratorCSharp.INDENT);
809: 
810: 	if (sDocComment != null) {
811: 	    // Fix Bug in documentation manager.defaultFor --> look for current INDENT
812: 	    // and use it
813: 	    for (int i = sDocComment.indexOf ('\n');
814: 		 i >= 0 && i < sDocComment.length();
815: 		 i = sDocComment.indexOf ('\n', i + 1)) {
816: 		sDocComment = sDocComment.substring (0, i + 1) +
817: 		    INDENT + sDocComment.substring (i + 1);
818: 	    }
819: 	}
820: 
821: 	// Extract constraints
822: 	Collection cConstraints = me.getConstraints();
823: 
824: 	if (cConstraints.size() == 0) {
825: 	    return (sDocComment != null) ? (sDocComment) : ("");
826: 	}
827: 
828: 	// Prepare doccomment
829: 	if (sDocComment != null) {
830: 	    // Just remove closing */
831: 	    sDocComment = sDocComment.substring (0, sDocComment.indexOf ("*/") + 1);
832: 	}
833: 	else {
834: 	    if (VERBOSE) {
835: 		sDocComment = INDENT + "/**\n" +
836: 		    INDENT + " * \n" +
837: 		    INDENT + " *";
838: 	    } else {
839: 		sDocComment = "";
840: 	    }
841: 	}
842: 
843: 	// Add each constraint
844: 
845: 	class TagExtractor extends tudresden.ocl.parser.analysis.DepthFirstAdapter {
846: 	    private LinkedList m_llsTags = new LinkedList();
847: 	    private String m_sConstraintName;
848: 	    private int m_nConstraintID = 0;
849: 
850: 	    public TagExtractor (String sConstraintName) {
851: 		super();
852: 
853: 		m_sConstraintName = sConstraintName;
854: 	    }
855: 
856: 	    public Iterator getTags() {
857: 		return m_llsTags.iterator();
858: 	    }
859: 
860: 	    public void caseAConstraintBody (tudresden.ocl.parser.node.AConstraintBody node) {
861: 		// We don't care for anything below this node, so we do not use apply anymore.
862: 		String sKind = (node.getStereotype() != null) ?
863: 		    (node.getStereotype().toString()) :
864: 		    (null);
865: 		String sExpression = (node.getExpression() != null) ?
866: 		    (node.getExpression().toString()) :
867: 		    (null);
868: 		String sName = (node.getName() != null) ?
869: 		    (node.getName().getText()) :
870: 		    (m_sConstraintName + "_" + (m_nConstraintID++));
871: 
872: 		if ((sKind == null) ||
873: 		    (sExpression == null)) {
874: 		    return;
875: 		}
876: 
877: 		String sTag;
878: 		if (sKind.equals ("inv ")) {
879: 		    sTag = "@invariant ";
880: 		}
881: 		else if (sKind.equals ("post ")) {
882: 		    sTag = "@post-condition ";
883: 		}
884: 		else if (sKind.equals ("pre ")) {
885: 		    sTag = "@pre-condition ";
886: 		}
887: 		else {
888: 		    return;
889: 		}
890: 
891: 		sTag += sName + ": " + sExpression;
892: 		m_llsTags.addLast (sTag);
893: 	    }
894: 	}
895: 
896: 	tudresden.ocl.check.types.ModelFacade mf = new org.argouml.ocl.ArgoFacade (me);
897: 	for (Iterator i = cConstraints.iterator(); i.hasNext();) {
898: 	    MConstraint mc = (MConstraint) i.next();
899: 
900: 	    try {
901: 		tudresden.ocl.OclTree otParsed =
902: 		    tudresden.ocl.OclTree.createTree(mc.getBody().getBody(),
903: 						     mf);
904: 
905: 		TagExtractor te = new TagExtractor (mc.getName());
906: 		otParsed.apply (te);
907: 
908: 		for (Iterator j = te.getTags(); j.hasNext();) {
909: 		    sDocComment += " " + j.next() + "\n" + INDENT + " *";
910: 		}
911: 	    }
912: 	    catch (java.io.IOException ioe) {
913: 		// Nothing to be done, should not happen anyway ;-)
914: 	    }
915: 	}
916: 
917: 	sDocComment += "/";
918: 
919: 	return sDocComment;
920:     }
