131: class UMLAction extends AbstractAction {
132: 
133:   public UMLAction(String name) { this(name, true); }
134:   
135:   public UMLAction(String name, boolean global) { 
136:     super(name, loadIconResource(imageName(name), name));
137:     putValue(Action.SHORT_DESCRIPTION, name);
138:     if (global) Actions._allActions.addElement(this);
139:   }
140: 
141:   protected static ImageIcon loadIconResource(String imgName, String desc) {
142:     ImageIcon res = null;
143:     try {
144:       java.net.URL imgURL = UMLAction.class.getResource(imgName);
145:       return new ImageIcon(imgURL, desc);
146:     }
147:     catch (Exception ex) {
148:       return new ImageIcon(desc);
149:     }
150:   }
151: 
152:   protected static String imageName(String name) {
153:     return "/uci/Images/" + stripJunk(name) + ".gif";
154:   }
