160:     System.out.println("pushed " + getValue(Action.NAME));
161:     StatusBar sb = ProjectBrowser.TheInstance.getStatusBar();
162:     sb.doFakeProgress(stripJunk(getValue(Action.NAME).toString()), 100);
163:     History.TheHistory.addItem("pushed " + getValue(Action.NAME));
164:     Actions.updateAllEnabled();
165:   }
