131: class UMLAction extends AbstractAction {
132: 
133:   public UMLAction(String name) { this(name, true); }
134:   
135:   public UMLAction(String name, boolean global) { 
136:     super(name, loadIconResource(imageName(name), name));
137:     putValue(Action.SHORT_DESCRIPTION, name);
138:     if (global) Actions._allActions.addElement(this);
139:   }
140: 
141:   protected static ImageIcon loadIconResource(String imgName, String desc) {
142:     ImageIcon res = null;
143:     try {
144:       java.net.URL imgURL = UMLAction.class.getResource(imgName);
145:       return new ImageIcon(imgURL, desc);
146:     }
147:     catch (Exception ex) {
148:       return new ImageIcon(desc);
149:     }
150:   }
151: 
152:   protected static String imageName(String name) {
153:     return "/uci/Images/" + stripJunk(name) + ".gif";
154:   }
155:   
156: 
157:   /** Perform the work the action is supposed to do. */
158:   // needs-more-work: should actions run in their own threads?
159:   public void actionPerformed(ActionEvent e) {
160:     System.out.println("pushed " + getValue(Action.NAME));
161:     StatusBar sb = ProjectBrowser.TheInstance.getStatusBar();
162:     sb.doFakeProgress(stripJunk(getValue(Action.NAME).toString()), 100);
163:     History.TheHistory.addItem("pushed " + getValue(Action.NAME));
164:     Actions.updateAllEnabled();
165:   }
166: 
167: 
168:   public void updateEnabled(Object target) { setEnabled(shouldBeEnabled()); }
169:   public void updateEnabled() { setEnabled(shouldBeEnabled()); }
170: 
171:   /** return true if this action should be available to the user. This
172:    *  method should examine the ProjectBrowser that owns it.  Sublass
173:    *  implementations of this method should always call
174:    *  super.shouldBeEnabled first. */
175:   public boolean shouldBeEnabled() { return true; }
176: 
177: 
178:   protected static String stripJunk(String s) {
179:     String res = "";
180:     int len = s.length();
181:     for (int i = 0; i < len; i++) {
182:       char c = s.charAt(i);
183:       if (Character.isJavaLetterOrDigit(c)) res += c;
184:     }
185:     return res;
186:   }
187: } /* end class UMLAction */
